/**
 * Dashboard Executivo UHN consolidado (Versão 100% JavaScript)
 * Traduzido do Python para replicar TODAS as informações, tabelas e avisos.
 */

async function renderizar_visao_geral() {
    const root = document.getElementById('dash-root');
    root.innerHTML = '<div class="flex items-center justify-center h-64 text-uhnBlue font-bold"><i class="fa-solid fa-spinner fa-spin mr-3"></i> Processando Dados...</div>';

    // -----------------------------------------------------------------------------
    // TEMA E LIMITES
    // -----------------------------------------------------------------------------
    const AZUL_ESCURO = "#426B86", AZUL = "#6F9FBE", AZUL_CLARO = "#82BFD8", VERDE = "#78B990";
    const AMARELO = "#E6C568", LARANJA = "#DDA06F", VERMELHO = "#D98189", ROXO = "#9B87C7";
    const CURVA_LB = "#5B879F", CURVA_PROJETADO = "#82BFD8", CURVA_REALIZADO = "#92B26E";
    const TEXTO = "#17324D", TEXTO_SUAVE = "#66788A", FUNDO = "#F5F8FA", BORDA = "#E1E8EC";

    const LIMITES = { desvio_atencao: 0.03, desvio_critico: 0.07, recurso_atencao: 0.10 };

    // -----------------------------------------------------------------------------
    // FUNÇÕES DE APOIO
    // -----------------------------------------------------------------------------
    function parseNum(val) {
        if (val === null || val === undefined || val === '') return NaN;
        if (typeof val === 'number') return val;
        let s = String(val).trim().replace('%', '');
        if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
        else if (s.includes(',')) s = s.replace(',', '.');
        return parseFloat(s);
    }
    function normalizarPct(val) {
        let v = parseNum(val); return (v > 1.5) ? v / 100 : v;
    }
    function fmtPct(val, casas = 1, sinal = false) {
        if (isNaN(val) || val === null) return "—";
        let num = val * 100;
        let s = Math.abs(num).toFixed(casas).replace('.', ',');
        if (sinal) return (num >= 0 ? '+' : '-') + s + '%';
        return s + '%';
    }
    function fmtInt(val) { return (isNaN(val) || val === null) ? "—" : Math.round(val).toLocaleString('pt-BR'); }
    function fmtMoney(val) {
        if (isNaN(val) || val === null) return "—";
        let n = Math.abs(val);
        if (n >= 1000000) return `R$ ${(val/1000000).toFixed(1).replace('.',',')} MM`;
        if (n >= 1000) return `R$ ${(val/1000).toFixed(1).replace('.',',')} mil`;
        return `R$ ${val.toLocaleString('pt-BR')}`;
    }
    function fmtData(val, curto = false) {
        if (!val) return "—";
        let d = new Date(val);
        if (typeof val === 'number') d = new Date(Math.round((val - 25569)*86400*1000));
        if (isNaN(d.getTime())) return "—";
        const dia = String(d.getUTCDate()).padStart(2, '0');
        const mes = String(d.getUTCMonth() + 1).padStart(2, '0');
        const ano = curto ? String(d.getUTCFullYear()).slice(-2) : d.getUTCFullYear();
        return `${dia}/${mes}/${ano}`;
    }
    function parseDataStr(val) {
        if (!val) return null;
        let d = new Date(val);
        if (typeof val === 'number') d = new Date(Math.round((val - 25569)*86400*1000));
        if (isNaN(d.getTime())) return null;
        return d;
    }
    function escapeHTML(str) {
        if (!str) return "";
        return String(str).replace(/[&<>'"]/g, tag => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;'
        }[tag]));
    }
    function _premissa_html(texto) {
        return `<div class="uhn-premissa"><strong>PREMISSA · </strong>${escapeHTML(texto)}</div>`;
    }

    // -----------------------------------------------------------------------------
    // CARREGAMENTO DE DADOS
    // -----------------------------------------------------------------------------
    const [fisica, financeira, recursos, resumo_exec, marcos, riscos] = await Promise.all([
        consultar('SELECT * FROM planilha_21'), consultar('SELECT * FROM planilha_22'), consultar('SELECT * FROM planilha_23'),
        consultar('SELECT * FROM planilha_24'), consultar('SELECT * FROM planilha_27'), consultar('SELECT * FROM planilha_28')
    ]);

    if (!fisica || fisica.length === 0) {
        root.innerHTML = '<div class="bg-blue-50 text-blue-700 p-4 rounded">Importe a Planilha 21 — Planejamento / Curva S Física para visualizar este painel.</div>';
        return;
    }

    // -----------------------------------------------------------------------------
    // PROCESSAMENTO
    // -----------------------------------------------------------------------------
    fisica.forEach(r => {
        r.numero_semana = parseNum(r.numero_semana);
        r.eap = parseNum(r.eap);
        r.previsto_lb_acum = normalizarPct(r.previsto_lb_acum);
        r.realizado_acum = normalizarPct(r.realizado_acum);
        r.projetado_acum = normalizarPct(r.projetado_acum);
    });

    let geral = fisica.filter(r => r.eap === 0);
    if (geral.length === 0) {
        let first = fisica.find(r => r.eap !== undefined && !isNaN(r.eap));
        if (first) geral = fisica.filter(r => r.eap === first.eap);
    }
    geral.sort((a, b) => a.numero_semana - b.numero_semana);

    let semana_corte = 0, previsto = NaN, realizado = NaN, desvio = NaN, projecao_final = NaN;
    let total_semanas = geral.length > 0 ? Math.max(...geral.map(r => r.numero_semana)) : 0;
    let projeto = "PROJETO UHN";

    if (geral.length > 0) {
        let realizados = geral.filter(r => r.realizado_acum > 0);
        let linhaCorte = realizados.length > 0 ? realizados[realizados.length - 1] : geral[geral.length - 1];
        semana_corte = linhaCorte.numero_semana;
        previsto = linhaCorte.previsto_lb_acum;
        realizado = linhaCorte.realizado_acum;
        desvio = realizado - previsto;
        projecao_final = geral[geral.length - 1].projetado_acum;
        if (geral[geral.length - 1].descricao_da_eap) projeto = geral[geral.length - 1].descricao_da_eap;
    }

    let eaps_total = new Set(fisica.filter(r => r.eap !== 0).map(r => r.eap)).size;

    let eapsAgrupadas = {};
    fisica.filter(r => r.eap !== 0 && r.numero_semana <= semana_corte).forEach(r => {
        if (!eapsAgrupadas[r.eap] || eapsAgrupadas[r.eap].numero_semana < r.numero_semana) eapsAgrupadas[r.eap] = r;
    });
    let resumo = Object.values(eapsAgrupadas).map(r => {
        let prev = r.previsto_lb_acum, real = r.realizado_acum;
        return { EAP: r.eap, Disciplina: r.descricao_da_eap || `EAP ${r.eap}`, Previsto: prev, Realizado: real, Desvio: real - prev };
    }).sort((a, b) => a.Desvio - b.Desvio).slice(0, 9);

    let fin_prev = NaN, fin_real = NaN;
    let fin_validos = financeira.filter(r => parseNum(r.realizado_acum) > 0);
    if (fin_validos.length > 0) {
        let last = fin_validos[fin_validos.length - 1];
        fin_prev = parseNum(last.previsto_lb_acum);
        fin_real = parseNum(last.realizado_acum);
    }

    let efetivo_uhn = NaN, efetivo_sub = NaN, semana_efetivo = "—";
    if (recursos.length > 0) {
        let recSemanas = recursos.filter(r => parseNum(r.numero_semana) <= semana_corte);
        if (recSemanas.length > 0) {
            semana_efetivo = Math.max(...recSemanas.map(r => parseNum(r.numero_semana)));
            let corteRec = recSemanas.filter(r => parseNum(r.numero_semana) === semana_efetivo);
            efetivo_uhn = corteRec.reduce((sum, r) => sum + (parseNum(r.efetivo_consorcio_uhn) || 0), 0);
            efetivo_sub = corteRec.reduce((sum, r) => sum + (parseNum(r.efetivo_subcontratados) || 0), 0);
            if (efetivo_uhn === 0 && efetivo_sub === 0 && corteRec[0].vinculo) {
                efetivo_uhn = corteRec.filter(r => String(r.vinculo).toLowerCase().includes('uhn')).reduce((s, r) => s + (parseNum(r.realizado)||0), 0);
                efetivo_sub = corteRec.filter(r => String(r.vinculo).toLowerCase().includes('subcontrat')).reduce((s, r) => s + (parseNum(r.realizado)||0), 0);
            }
        }
    }

    // Marcos
    const hoje = new Date();
    hoje.setHours(0,0,0,0);
    let marcos_concluidos = marcos.filter(r => String(r.situacao).toLowerCase().includes('conclu')).length;
    let lista_marcos = marcos.map(m => {
        let proj = parseDataStr(m.data_projetada) || parseDataStr(m.data_contratual);
        let real = parseDataStr(m.data_realizada);
        let inf = String(m.situacao || "").trim();
        let situacao = "No prazo", cor = LARANJA, dot = "", ordem = 1;
        if (real || inf.toLowerCase().includes("conclu")) { situacao = "Concluído"; cor = VERDE; dot = "done"; ordem = 0; }
        else if (proj && proj < hoje) { let dias = Math.floor((hoje - proj)/(1000*60*60*24)); situacao = `Atrasado · ${dias} d`; cor = VERMELHO; dot = "pulse"; ordem = 3; }
        else if (proj && proj <= new Date(hoje.getTime() + 30*24*60*60*1000)) { let dias = Math.floor((proj - hoje)/(1000*60*60*24)); situacao = `Prazo próximo · ${Math.max(0, dias)} d`; cor = LARANJA; dot = "pulse"; ordem = 2; }
        else if (inf.toLowerCase().includes("atras") || inf.toLowerCase().includes("fora")) { situacao = "Fora do prazo"; cor = VERMELHO; dot = "pulse"; ordem = 3; }
        else { situacao = inf || "No prazo"; cor = LARANJA; dot = ""; ordem = 1; }
        return { desc: m.descricao_do_marco, proj, real, inf, situacao, cor, dot, ordem };
    }).sort((a,b) => b.ordem - a.ordem || (a.proj && b.proj ? a.proj - b.proj : 0)).slice(0, 8);

    // Riscos
    let riscos_criticos = riscos.filter(r => String(r.severidade).toLowerCase().includes('críti') || String(r.severidade).toLowerCase().includes('criti')).length;
    let ordem_r = {"crítica":6, "critica":6, "muito alta":5, "alta":4, "média":3, "media":3, "baixa":2, "muito baixa":1};
    let lista_riscos = riscos.map(r => {
        let sev = String(r.severidade||"").trim().toLowerCase();
        let ord = ordem_r[sev] || 0;
        let cor = (sev.includes("críti") || sev.includes("criti") || sev.includes("muito alta")) ? VERMELHO : (sev.includes("alta") ? LARANJA : (sev.includes("média")||sev.includes("media") ? AMARELO : VERDE));
        return { evento: r.evento_do_risco, impacto: r.severidade || "Não informado", acao: r.plano_de_resposta, resp: r.responsavel, cor, ord };
    }).sort((a,b) => b.ord - a.ord).slice(0, 5);

    // CSS Completo do Python
    const style = document.createElement('style');
    style.innerHTML = `
        .uhn-project {display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px 18px; margin:.15rem .15rem .48rem; padding:2px 0;}
        .uhn-project h2 {color:${TEXTO}; font-size:1.28rem; margin:0; font-weight:950; letter-spacing:.012em; white-space:nowrap;}
        .uhn-meta {display:flex; align-items:center; justify-content:flex-end; flex-wrap:wrap; gap:7px;}
        .uhn-meta-item {display:inline-flex; align-items:center; gap:5px; min-height:26px; padding:3px 9px; border:1px solid #DCE7EF; border-radius:7px; background:#FFFFFF; color:${TEXTO_SUAVE}; font-size:.70rem; font-weight:750; box-shadow:0 2px 7px #426B8608;}
        .uhn-meta-item strong {color:${AZUL_ESCURO}; font-size:.84rem; font-weight:950;}
        .uhn-meta-item.corte {border-color:#C7DCE8; background:#F1F7FA; color:${AZUL_ESCURO};}
        .uhn-cards-grid {display:grid; grid-template-columns:repeat(auto-fit, minmax(200px, 1fr)); gap:10px; margin-bottom:20px;}
        .uhn-card {background:#fff; border:1px solid ${BORDA}; border-radius:9px; padding:10px; box-shadow:0 3px 12px #426B860B; border-top:4px solid var(--accent); min-height:100px; display:flex; flex-direction:column; justify-content:center;}
        .uhn-card-title {font-size:.63rem; color:#557087; font-weight:900; text-align:center;}
        .uhn-card-main {display:flex; align-items:center; justify-content:center; gap:7px; margin-top:5px;}
        .uhn-card-icon {width:27px; height:27px; border-radius:50%; color:#fff; background:var(--accent); display:flex; align-items:center; justify-content:center; font-size:14px; box-shadow:0 3px 8px color-mix(in srgb, var(--accent) 30%, transparent);}
        .uhn-card-value {font-size:1.24rem; font-weight:900; color:var(--accent);}
        .uhn-card-detail {font-size:.62rem; text-align:center; color:${TEXTO_SUAVE}; margin-top:5px;}

        .uhn-panel {background:#fff; border:1px solid ${BORDA}; border-radius:9px; padding:12px 13px 5px; margin-bottom:15px; box-shadow:0 3px 14px #063b6709;}
        .uhn-panel-title {color:${AZUL_ESCURO}; font-size:.79rem; font-weight:900; border-bottom:1px solid ${BORDA}; padding-bottom:7px; margin-bottom:10px;}
        .uhn-curve-head {display:grid; grid-template-columns:1fr 108px; align-items:center; gap:12px; padding:7px 5px 5px;}
        .uhn-curve-name {display:flex; align-items:center; gap:10px; color:${AZUL_ESCURO}; font-size:1.18rem; font-weight:900;}
        .uhn-curve-icon {width:34px; height:34px; border-radius:8px; background:#EDF5F8; color:${AZUL}; display:flex; align-items:center; justify-content:center; font-size:1.18rem;}
        .uhn-curve-metrics {font-size:.79rem; color:${TEXTO}; font-weight:850; margin-top:7px;}
        .uhn-week-badge {min-width:92px; height:58px; padding:0 10px; border:1px solid #C4D8E3; border-left:5px solid ${AZUL}; border-radius:10px; background:linear-gradient(135deg,#F8FBFC,#EDF5F8); display:flex; flex-direction:column; align-items:center; justify-content:center; color:${AZUL_ESCURO}; font-size:.64rem; font-weight:900;}
        .uhn-week-badge strong {font-size:1.14rem; display:block;}

        .uhn-eap-table {width:100%; border-collapse:collapse; margin-bottom:7px;}
        .uhn-eap-table th {background:#F8FBFD; color:${AZUL_ESCURO}; font-weight:900; padding:7px 8px; border-bottom:2px solid ${BORDA}; text-align:center; font-size:.68rem;}
        .uhn-eap-table td {padding:6px 8px; border-bottom:1px solid #E8EFF5; text-align:center; color:${TEXTO}; font-size:.71rem;}
        .uhn-eap-code {display:inline-flex; align-items:center; justify-content:center; min-width:25px; height:19px; border-radius:10px; background:#E7F1F8; color:${AZUL_ESCURO}; font-size:.62rem; font-weight:900; margin-right:7px;}
        .uhn-progress-wrap {display:flex; align-items:center; gap:7px;}
        .uhn-progress-bg {flex:1; height:10px; background:#E7EDF2; border-radius:6px; overflow:hidden;}
        .uhn-progress-fill {height:100%; border-radius:6px;}
        .uhn-status-dot {display:inline-block; width:11px; height:11px; border-radius:50%; box-shadow:0 0 0 3px #FFFFFF, 0 0 0 4px #E1E8EC;}

        .uhn-insight {display:grid; grid-template-columns:38px 1fr; gap:10px; padding:10px 3px; border-bottom:1px solid #EDF2F7;}
        .uhn-insight-icon {font-size:1.38rem; text-align:center; font-weight:900;}
        .uhn-insight strong {display:block; font-size:.82rem; margin-bottom:4px;}
        .uhn-insight span {display:block; color:${TEXTO_SUAVE}; font-size:.76rem;}

        .uhn-premissa {margin:5px 2px 9px; padding:7px 9px; border-radius:7px; border:1px solid #DCE7EF; border-left:4px solid ${AZUL}; background:#F6FAFC; color:#5C7183; font-size:.65rem;}
        .uhn-premissa strong {color:${AZUL_ESCURO}; font-size:.64rem;}

        .uhn-alert {display:grid; grid-template-columns:38px 1fr; gap:11px; align-items:flex-start; border-radius:8px; padding:14px 16px; margin-top:10px; font-size:.86rem; font-weight:600; background:#FFF9F1; color:#74543A; border:1px solid #EAD7C2; border-left:5px solid ${LARANJA};}
        .uhn-alert-icon {width:32px; height:32px; display:flex; align-items:center; justify-content:center; border-radius:50%; background:${LARANJA}; color:#FFFFFF; font-size:1.05rem; font-weight:950;}
        .uhn-alert-title {display:block; color:#765035; font-size:.94rem; font-weight:950; margin-bottom:5px;}

        .uhn-marcos-table, .uhn-riscos-table {width:100%; border-collapse:collapse;}
        .uhn-marcos-table th, .uhn-riscos-table th {padding:9px 10px; background:#F4F7FA; color:#718096; font-size:.70rem; font-weight:800; text-align:left; border-bottom:1px solid ${BORDA};}
        .uhn-marcos-table td, .uhn-riscos-table td {padding:8px 10px; color:${TEXTO}; font-size:.72rem; border-bottom:1px solid #E8EEF4;}
        .uhn-marco-dot {display:inline-block; width:11px; height:11px; border-radius:50%; background:var(--status); margin-right:5px;}
        .uhn-impacto-badge {display:inline-block; min-width:54px; padding:4px 7px; border-radius:12px; color:#FFFFFF; font-size:.64rem; font-weight:900; text-align:center;}
    `;
    document.head.appendChild(style);

    // Render Cards
    function renderCard(titulo, valor, detalhe, cor, icone) {
        return `<div class="uhn-card" style="--accent:${cor}">
          <div class="uhn-card-title">${titulo}</div>
          <div class="uhn-card-main"><div class="uhn-card-icon">${icone}</div>
          <div class="uhn-card-value">${valor}</div></div>
          <div class="uhn-card-detail">${detalhe}</div>
        </div>`;
    }

    // Ponto de atenção
    let htmlAlerta = "";
    if (resumo_exec.length > 0) {
        let att = resumo_exec.filter(r => (r.pontos_de_atencao || "").trim() !== "");
        if (att.length > 0) {
            att.sort((a,b) => parseNum(a.numero_semana) - parseNum(b.numero_semana));
            let u = att[att.length - 1];
            htmlAlerta = `<div class="uhn-alert"><span class="uhn-alert-icon">!</span><div>
                <strong class="uhn-alert-title">PONTO DE ATENÇÃO — SEMANA ${u.numero_semana||""}</strong>
                <span class="uhn-alert-text">${escapeHTML(u.pontos_de_atencao)}</span>
            </div></div>` + _premissa_html("Fonte P24. Apresenta o último ponto_de_atencao não vazio.");
        }
    }

    let htmlContent = `
        <div class="uhn-project">
            <h2>RESUMOS GERENCIAIS</h2>
            <div class="uhn-meta">
                <span class="uhn-meta-item corte">SEMANA DE CORTE <strong>${semana_corte}</strong></span>
                <span class="uhn-meta-item">SEMANAS TOTAIS <strong>${total_semanas}</strong></span>
                <span class="uhn-meta-item">EAPs <strong>${eaps_total}</strong></span>
            </div>
        </div>

        <div class="uhn-cards-grid">
            ${renderCard("AVANÇO PLANEJADO", fmtPct(previsto), "Linha de base no corte", AZUL, "▥")}
            ${renderCard("AVANÇO REALIZADO", fmtPct(realizado), `Semana ${semana_corte}`, VERDE, "●")}
            ${renderCard("DESVIO FÍSICO", fmtPct(desvio, 1, true), "Realizado − planejado", (desvio>=0?VERDE: (desvio<=-LIMITES.desvio_critico?VERMELHO:LARANJA)), (desvio<0?"↘":"↗"))}
            ${renderCard("EFETIVO CONSÓRCIO UHN", fmtInt(efetivo_uhn), `Semana ${semana_efetivo}`, AZUL, "♟")}
            ${renderCard("EFETIVO SUBCONTRATADOS", fmtInt(efetivo_sub), `Semana ${semana_efetivo}`, AZUL_CLARO, "♜")}
            ${renderCard("REALIZADO FINANCEIRO", fmtMoney(fin_real), `Previsto: ${fmtMoney(fin_prev)}`, ROXO, "◆")}
            ${renderCard("MARCOS CONCLUÍDOS", marcos_concluidos, `de ${marcos.length} monitorados`, VERDE, "✓")}
            ${renderCard("RISCOS CRÍTICOS", riscos_criticos, `de ${riscos.length} cadastrados`, VERMELHO, "!")}
        </div>
        ${_premissa_html("Indicadores consolidados pelas fontes P21 (avanço físico), P22 (financeiro), P23 (efetivo), P27 (marcos) e P28 (riscos).")}

        <div class="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-4">
            <div class="lg:col-span-2 uhn-panel" style="min-width: 0;">
                <div class="uhn-panel-title">CURVA FÍSICA ACUMULADA</div>
                <div class="uhn-curve-head">
                    <div>
                        <div class="uhn-curve-name"><span class="uhn-curve-icon">▰</span> ${escapeHTML(projeto)}</div>
                        <div class="uhn-curve-metrics">
                            Previsto: <b style="color:${CURVA_LB}">${fmtPct(previsto)}</b> | 
                            Realizado: <b style="color:${CURVA_REALIZADO}">${fmtPct(realizado)}</b> | 
                            Desvio: <b style="color:${desvio>=0?VERDE:VERMELHO}">${fmtPct(desvio,1,true)}</b>
                        </div>
                    </div>
                    <div class="uhn-week-badge"><strong>${semana_corte}</strong>SEM. ATUAL</div>
                </div>
                <div id="plot-curva" style="width:100%; height:350px;"></div>
                ${_premissa_html("Fonte P21. A semana de corte corresponde ao último período da EAP geral com realizado acumulado maior que zero.")}
            </div>

            <div class="uhn-panel" style="min-width: 0;"><div class="uhn-panel-title">INSIGHTS GERENCIAIS</div>
                <div class="mt-4 space-y-4">
                    <div class="uhn-insight"><div class="uhn-insight-icon" style="color:${desvio>=0?VERDE:(desvio<=-LIMITES.desvio_critico?VERMELHO:LARANJA)}">${desvio>=0?"✓": (desvio<=-LIMITES.desvio_critico?"⚠":"↘")}</div>
                    <div><strong style="color:${desvio>=0?VERDE:(desvio<=-LIMITES.desvio_critico?VERMELHO:LARANJA)}">${desvio>=0?"Desempenho físico":"Tendência de atenção"}</strong><span>O desvio físico atual é de ${fmtPct(desvio,1,true)}.</span></div></div>

                    ${riscos_criticos > 0 ? `<div class="uhn-insight"><div class="uhn-insight-icon" style="color:${VERMELHO}">◉</div>
                    <div><strong style="color:${VERMELHO}">Risco Crítico</strong><span>Existem ${riscos_criticos} riscos que exigem atenção imediata.</span></div></div>` : 
                    `<div class="uhn-insight"><div class="uhn-insight-icon" style="color:${VERDE}">◉</div>
