/**
 * Painel Executivo de SMS - integração das planilhas P31 a P36.
 * ---------------------------------------------------------------------------
 * Conversão do painel Streamlit/Altair/pandas para JavaScript puro:
 *   st.columns / st.markdown  -> HTML + CSS (o CSS original foi preservado)
 *   altair                    -> Plotly (já carregado no sandbox)
 *   pandas.DataFrame          -> arrays de objetos
 *
 * As colunas já chegam normalizadas do runtime (`Avanço Físico (%)` vira
 * `avanco_fisico`), então `coluna()` compara sempre pela forma normalizada,
 * exatamente como o `_coluna` do Python fazia.
 */

const root = document.getElementById('dash-root');

const MESES = {
    JANEIRO: 1, FEVEREIRO: 2, MARCO: 3, ABRIL: 4,
    MAIO: 5, JUNHO: 6, JULHO: 7, AGOSTO: 8,
    SETEMBRO: 9, OUTUBRO: 10, NOVEMBRO: 11, DEZEMBRO: 12
};

// Paleta pastel UHNINTEGRA: cores suavizadas, mantendo contraste suficiente
// para indicadores, gráficos e estados de atenção.
const AZUL = '#5E8FA8';
const AZUL_CLARO = '#76B1C3';
const VERDE = '#76B28A';
const LARANJA = '#D5A15F';
const VERMELHO = '#D67C86';
const ROXO = '#9582B9';

const MESES_ABREV = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];

// ---------------------------------------------------------------------------
// Helpers equivalentes aos do Python
// ---------------------------------------------------------------------------

/** Equivale a _norm: sem acento, minúsculo, não-alfanumérico vira "_". */
function norm(valor) {
    if (valor === null || valor === undefined) return '';
    const bruto = String(valor);
    if (['<NA>', 'nan', 'NaT', 'None'].includes(bruto)) return '';
    return bruto
        .normalize('NFKD').replace(/[̀-ͯ]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
}

/** Equivale a _coluna: acha a coluna real a partir de nomes candidatos. */
function coluna(linhas, ...candidatos) {
    if (!linhas || !linhas.length) return null;
    const existentes = new Map();
    for (const chave of Object.keys(linhas[0])) existentes.set(norm(chave), chave);
    for (const candidato of candidatos) {
        const n = norm(candidato);
        if (existentes.has(n)) return existentes.get(n);
    }
    return null;
}

/** Equivale a _texto: série de strings com valor padrão para vazios. */
function texto(linhas, col, padrao = 'Não informado') {
    return linhas.map(linha => {
        if (col === null) return padrao;
        const v = linha[col];
        if (v === null || v === undefined) return padrao;
        const s = String(v).trim();
        return (s === '' || s === 'nan' || s === 'NaT' || s === '<NA>') ? padrao : s;
    });
}

/** Equivale a _numero: converte para número aceitando vírgula decimal. */
function numero(linhas, col, padrao = 0) {
    return linhas.map(linha => {
        if (col === null) return padrao;
        const v = linha[col];
        if (v === null || v === undefined || v === '') return padrao;
        if (typeof v === 'number') return isNaN(v) ? padrao : v;
        const n = parseFloat(String(v).trim().replace(/\s/g, '').replace(',', '.'));
        return isNaN(n) ? padrao : n;
    });
}

/** Extrai o primeiro número de textos como "337 - desvios". */
function numeroTexto(valor) {
    if (valor === null || valor === undefined) return 0;
    const achado = String(valor).match(/-?\d+(?:[.,]\d+)?/);
    return achado ? parseFloat(achado[0].replace(',', '.')) : 0;
}

function mesNumero(valor) {
    const n = norm(valor).toUpperCase();
    if (MESES[n] !== undefined) return MESES[n];
    const numerico = parseInt(valor, 10);          // a P32 traz o mês já numérico
    return (numerico >= 1 && numerico <= 12) ? numerico : null;
}

/** Monta a competência (dia 1) a partir de mês e ano. Em UTC, para não sofrer fuso. */
function montarData(mes, ano) {
    const m = mesNumero(mes);
    const a = parseInt(ano, 10);
    if (!m || isNaN(a)) return null;
    return new Date(Date.UTC(a, m - 1, 1));
}

/** Converte qualquer célula de data em Date; trata o serial numérico do Excel. */
function paraData(valor) {
    if (valor === null || valor === undefined || valor === '') return null;
    if (valor instanceof Date) return isNaN(valor.getTime()) ? null : valor;
    if (typeof valor === 'number') {
        const d = new Date(Math.round((valor - 25569) * 86400 * 1000));
        return isNaN(d.getTime()) ? null : d;
    }
    const s = String(valor).trim();
    // dd/mm/aaaa é o formato que vem das planilhas de obra
    const br = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
    if (br) {
        const ano = br[3].length === 2 ? 2000 + parseInt(br[3], 10) : parseInt(br[3], 10);
        return new Date(Date.UTC(ano, parseInt(br[2], 10) - 1, parseInt(br[1], 10)));
    }
    const d = new Date(s);
    return isNaN(d.getTime()) ? null : d;
}

/** Trunca a data no primeiro dia do mês (equivale a to_period("M")). */
function inicioDoMes(data) {
    return data ? new Date(Date.UTC(data.getUTCFullYear(), data.getUTCMonth(), 1)) : null;
}

// ---------------------------------------------------------------------------
// Formatação
// ---------------------------------------------------------------------------

function fmtNum(valor, casas = 0) {
    const n = Number(valor);
    if (!isFinite(n)) return '—';
    return n.toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
}

function fmtPct(valor) {
    const n = Number(valor);
    if (!isFinite(n)) return '—';
    return n.toFixed(1).replace('.', ',') + '%';
}

function pct(numerador, denominador) {
    return denominador ? (Number(numerador) / Number(denominador)) * 100 : 0;
}

function rotuloMes(data) {
    return MESES_ABREV[data.getUTCMonth()] + '/' + String(data.getUTCFullYear()).slice(-2);
}

function competencia(data) {
    return String(data.getUTCMonth() + 1).padStart(2, '0') + '/' + data.getUTCFullYear();
}

function dataBR(data) {
    return String(data.getUTCDate()).padStart(2, '0') + '/' +
           String(data.getUTCMonth() + 1).padStart(2, '0') + '/' + data.getUTCFullYear();
}

function escapeHtml(valor) {
    let s = (valor === null || valor === undefined) ? '—' : String(valor).trim();
    if (s === '' || s === '<NA>' || s === 'nan' || s === 'NaT') s = '—';
    return s.replace(/[&<>"']/g, c =>
        ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])
    ).replace(/\n/g, '<br>');
}

const soma = arr => arr.reduce((a, b) => a + (Number(b) || 0), 0);

/** Ordena por Data e mantém só o último registro de cada competência. */
function ultimoPorData(linhas) {
    const ordenadas = linhas.slice().sort((a, b) => a.Data - b.Data);
    const porChave = new Map();
    for (const linha of ordenadas) porChave.set(+linha.Data, linha);
    return [...porChave.values()].sort((a, b) => a.Data - b.Data);
}

// ---------------------------------------------------------------------------
// Preparação das fontes (P31 a P36)
// ---------------------------------------------------------------------------

/** Indicadores mensais consolidados de HH, efetivo e segurança. */
function prepararP31(dados) {
    if (!dados || !dados.length) return [];
    const cMes = coluna(dados, 'Mes'), cAno = coluna(dados, 'Ano');

    const mapa = {
        'HH Contratada': 'Hher contratada', 'HH Subcontratada': 'Hher subcontratada', 'HH Total': 'Hher total',
        'Efetivo Total': 'Numero de empregados total', 'Efetivo Contratada': 'Numero de empregados contratada',
        'Efetivo Subcontratada': 'Numero empregados subcontratada', 'Ocorrências Ambientais': 'Ocorrência Ambiental',
        'Acidentes sem afastamento': 'Numero de acidentados sem afastamento',
        'Acidentes com afastamento': 'Numero de acidentados com afastamento',
        'Incidentes': 'Incidente Não Categorizado', 'Acidentados': 'Acidentados total',
        'Dias Perdidos': 'Dias perdidos', 'Dias Debitados': 'Dias debitados',
        'FTCA': 'FTCA', 'TFSA': 'TFSA', 'TOR': 'TOR', 'TAR': 'TAR', 'TG': 'TG', 'TAP': 'TAP'
    };

    const series = {};
    for (const [destino, origem] of Object.entries(mapa)) {
        series[destino] = numero(dados, coluna(dados, origem));
    }

    const saida = dados.map((linha, i) => {
        const registro = { Data: montarData(cMes ? linha[cMes] : null, cAno ? linha[cAno] : null) };
        for (const destino of Object.keys(mapa)) registro[destino] = series[destino][i];
        return registro;
    }).filter(r => r.Data);

    return ultimoPorData(saida);
}

/** Efetivo nominal e exposição detalhada. */
function prepararP32(dados) {
    if (!dados || !dados.length) return [];
    const cMes = coluna(dados, 'Mês', 'Mes'), cAno = coluna(dados, 'Ano');
    const empresa = texto(dados, coluna(dados, 'Contratada'));
    const vinculo = texto(dados, coluna(dados, 'Subcontratda', 'Subcontratada'), 'Não classificado');
    const funcao = texto(dados, coluna(dados, 'Função'));
    const funcionario = texto(dados, coluna(dados, 'Nome do Funcionário'));
    const dias = numero(dados, coluna(dados, 'Dias Trabalhados'));
    const horas = numero(dados, coluna(dados, 'Horas Trabalhada', 'Horas Trabalhadas'));

    return dados.map((linha, i) => ({
        Data: montarData(cMes ? linha[cMes] : null, cAno ? linha[cAno] : null),
        Empresa: empresa[i], 'Vínculo': vinculo[i], 'Função': funcao[i],
        'Funcionário': funcionario[i], Dias: dias[i], Horas: horas[i]
    })).filter(r => r.Data);
}

/** Ocorrências detalhadas e respectivas causas. */
function prepararP33(dados) {
    if (!dados || !dados.length) return [];
    const cData = coluna(dados, 'Data');
    const cAfast = coluna(dados, 'Data_do_afastamento', 'Data do afastamento');

    const empresa = texto(dados, coluna(dados, 'Contratada'));
    const setor = texto(dados, coluna(dados, 'Setor'));
    const acidentado = texto(dados, coluna(dados, 'Nome_do_acidentado', 'Nome do acidentado'), '—');
    const descricao = texto(dados, coluna(dados, 'Descrição_acidente_', 'Descricao acidente'));
    const natureza = texto(dados, coluna(dados, 'Natureza_da_lesão', 'Natureza da lesao'), '—');
    const local = texto(dados, coluna(dados, 'Localização_da_lesão', 'Localizacao da lesao'), '—');
    const causa = texto(dados, coluna(dados, 'Causas_básicas', 'Causas basicas'));
    const diasPerdidos = numero(dados, coluna(dados, 'Dias_perdidos', 'Dias perdidos'));

    return dados.map((linha, i) => {
        const afastamento = cAfast ? paraData(linha[cAfast]) : null;
        return {
            Data: cData ? paraData(linha[cData]) : null,
            Empresa: empresa[i], Setor: setor[i], Acidentado: acidentado[i],
            'Descrição': descricao[i], Natureza: natureza[i], 'Local da lesão': local[i],
            'Causa básica': causa[i], 'Data afastamento': afastamento,
            'Dias perdidos': diasPerdidos[i],
            'Com acidentado': acidentado[i] !== '—',
            'Com afastamento': afastamento !== null
        };
    }).filter(r => r.Data).sort((a, b) => a.Data - b.Data);
}

/** Indicadores preventivos, inspeções, desvios e atividades críticas. */
function prepararP34(dados) {
    if (!dados || !dados.length) return [];
    const cMes = coluna(dados, 'Mes'), cAno = coluna(dados, 'Ano');

    const numericos = {
        'Horas Treinamento': 'Horas de treinamento sms', 'Simulados': 'Controle simulados',
        'Horas não Trabalhadas': 'Horas nao trabalhadas',
        '% Afastamento CID-10': 'Percentual de afastamento por cid 10',
        'Inspeções Planejadas': 'No verificacoes inspecoes e auditorias sms planejadas',
        'Inspeções Realizadas': 'No verificacoes inspecoes e auditorias sms realizadas',
        'VCP Previstas': 'Vcps previstas', 'VCP Realizadas': 'Vcps realizadas'
    };

    const series = {};
    for (const [destino, origem] of Object.entries(numericos)) {
        series[destino] = numero(dados, coluna(dados, origem));
    }
    const desvios = texto(dados, coluna(dados, 'Numero de incidentes e desvios'), '0');
    const desviosVcp = texto(dados, coluna(dados, 'Desvios vcp total'), '0');
    const atividades = texto(dados, coluna(dados, 'Listagem de atividades criticas'), '—');
    const equipamentos = texto(dados, coluna(dados, 'Listagem de equipamentos criticos'), '—');

    const saida = dados.map((linha, i) => {
        const registro = { Data: montarData(cMes ? linha[cMes] : null, cAno ? linha[cAno] : null) };
        for (const destino of Object.keys(numericos)) registro[destino] = series[destino][i];
        registro['Desvios'] = numeroTexto(desvios[i]);
        registro['Desvios VCP'] = numeroTexto(desviosVcp[i]);
        registro['Atividades Críticas'] = atividades[i];
        registro['Equipamentos Críticos'] = equipamentos[i];
        return registro;
    }).filter(r => r.Data);

    return ultimoPorData(saida);
}

function prepararP35(dados) {
    if (!dados || !dados.length) return [];
    const cMes = coluna(dados, 'Mês', 'Mes');
    const treinamento = texto(dados, coluna(dados, 'Treinamentos_SMS', 'Treinamentos SMS'));
    const carga = numero(dados, coluna(dados, 'carga horária', 'carga horaria'));

    return dados.map((linha, i) => ({
        Data: inicioDoMes(cMes ? paraData(linha[cMes]) : null),
        Treinamento: treinamento[i],
        'Carga Horária': carga[i]
    })).filter(r => r.Data);
}

function prepararP36(dados) {
    if (!dados || !dados.length) return [];
    const cMes = coluna(dados, 'Mes', 'Mês');
    const residuos = texto(dados, coluna(dados, 'Controle_gerenciamento_ resíduos', 'Controle gerenciamento resíduos'));
    const rspr = texto(dados, coluna(dados, 'RSPR'));
    const rcsr = texto(dados, coluna(dados, 'RCSR'));

    return dados.map((linha, i) => ({
        Data: inicioDoMes(cMes ? paraData(linha[cMes]) : null),
        'Resíduos': residuos[i], RSPR: rspr[i], RCSR: rcsr[i]
    })).filter(r => r.Data).sort((a, b) => a.Data - b.Data);
}

// ---------------------------------------------------------------------------
// Blocos de HTML
// ---------------------------------------------------------------------------

function card(titulo, valor, nota, cor, percentual) {
    const barra = (percentual === null || percentual === undefined)
        ? ''
        : `<div class="sms-track"><i style="width:${Math.max(0, Math.min(100, percentual)).toFixed(1)}%"></i></div>`;
    return `<div class="sms-card" style="--cor:${cor}">
        <div class="sms-label">${titulo}</div>
        <div class="sms-value">${valor}</div>
        <div class="sms-note">${nota}</div>${barra}</div>`;
}

function tabelaOcorrenciasHtml(dados) {
    const fichas = dados.slice().sort((a, b) => b.Data - a.Data).map((r, i) => {
        const comAfastamento = Boolean(r['Com afastamento']);
        const afast = comAfastamento ? 'SIM' : 'NÃO';
        const cor = comAfastamento ? VERMELHO : VERDE;
        const rotulo = comAfastamento ? 'Com afastamento' : 'Sem afastamento';
        return `<article class="sms-occ-card" style="--impact:${cor}">
        <div class="sms-occ-main">
          <div class="sms-occ-head"><span>OCORRÊNCIA ${String(i + 1).padStart(2, '0')}</span><i></i></div>
          <div class="sms-occ-meta">
            <div class="sms-meta sms-meta-date"><small>Data</small><b>${dataBR(r.Data)}</b></div>
            <div class="sms-meta sms-meta-company"><small>Empresa</small><b>${escapeHtml(r.Empresa)}</b></div>
            <div class="sms-meta"><small>Setor</small><b>${escapeHtml(r.Setor)}</b></div>
            <div class="sms-meta"><small>Acidentado</small><b>${escapeHtml(r.Acidentado)}</b></div>
            <div class="sms-meta"><small>Natureza</small><b>${escapeHtml(r.Natureza)}</b></div>
            <div class="sms-meta"><small>Local da lesão</small><b>${escapeHtml(r['Local da lesão'])}</b></div>
          </div>
          <section class="sms-occ-section"><h4>Descrição da ocorrência</h4><div>${escapeHtml(r['Descrição'])}</div></section>
          <section class="sms-occ-section sms-occ-cause"><h4>Causa básica</h4><div>${escapeHtml(r['Causa básica'])}</div></section>
        </div>
        <aside class="sms-occ-impact"><small>Impacto</small><b>${afast}</b>
          <strong>${fmtNum(r['Dias perdidos'])} dia(s)</strong><span>${rotulo}</span></aside>
        </article>`;
    });
    return '<div class="sms-occ-list">' + fichas.join('') + '</div>';
}

function tabelaAmbientalHtml(dados) {
    const linhas = dados.slice().sort((a, b) => b.Data - a.Data).map(r => {
        const itens = String(r['Resíduos']).split('\n').map(x => x.trim()).filter(Boolean);
        const residuos = itens.length
            ? itens.map(x => `<span>${escapeHtml(x)}</span>`).join('')
            : '<span>Não informado</span>';
        return `<tr><td class="sms-date"><strong>${competencia(r.Data)}</strong></td>
        <td class="sms-env">${residuos}</td><td><span class="sms-status">${escapeHtml(r.RSPR)}</span></td>
        <td><span class="sms-status">${escapeHtml(r.RCSR)}</span></td></tr>`;
    });
    return `<div class="sms-table-wrap sms-environment"><table class="sms-table"><thead><tr>
    <th>Competência</th><th>Gerenciamento de resíduos</th><th>RSPR</th><th>RCSR</th></tr></thead><tbody>${linhas.join('')}</tbody></table></div>`;
}

