const CONFIG_PLOT = { responsive: true, displayModeBar: false };

/** Exposição ao risco: barras empilhadas de efetivo + linha de HH no eixo direito. */
function graficoExposicao(elemento, dados) {
    const periodos = dados.map(d => rotuloMes(d.Data));
    const maxEfetivo = Math.max(...dados.map(d => d['Efetivo Total']), 1) * 1.16;
    const maxHH = Math.max(...dados.map(d => d['HH Total']), 1) * 1.12;

    const series = [
        {
            x: periodos, y: dados.map(d => d['Efetivo Contratada']),
            name: 'Efetivo Contratada', type: 'bar', marker: { color: AZUL_CLARO, opacity: .96 },
            hovertemplate: '%{x}<br>Contratada: %{y:,.0f}<extra></extra>'
        },
        {
            x: periodos, y: dados.map(d => d['Efetivo Subcontratada']),
            name: 'Efetivo Subcontratada', type: 'bar', marker: { color: LARANJA, opacity: .96 },
            hovertemplate: '%{x}<br>Subcontratada: %{y:,.0f}<extra></extra>'
        },
        {
            // O total fica dentro da barra para nunca disputar espaço com a curva de HH.
            x: periodos, y: dados.map(d => d['Efetivo Total']),
            mode: 'text', type: 'scatter', showlegend: false, hoverinfo: 'skip',
            text: dados.map(d => fmtNum(d['Efetivo Total'])),
            textposition: 'bottom center',
            textfont: { color: 'white', size: 10, family: 'Inter, sans-serif' }
        },
        {
            x: periodos, y: dados.map(d => d['HH Total']),
            name: 'HH Total', type: 'scatter', mode: 'lines+markers', yaxis: 'y2',
            line: { color: AZUL, width: 4 },
            marker: { size: 9, color: AZUL, line: { color: 'white', width: 1 } },
            hovertemplate: '%{x}<br>HH: %{y:,.0f}<extra></extra>'
        }
    ];

    Plotly.newPlot(elemento, series, Object.assign({}, LAYOUT_BASE, {
        height: 390, barmode: 'stack',
        // margem direita folgada: o título do eixo de HH colidia com os valores
        margin: { t: 30, r: 78, b: 60, l: 55 },
        legend: { orientation: 'h', y: 1.12, x: 0 },
        xaxis: { title: '', tickangle: 0, gridcolor: '#E8EEF0' },
        yaxis: { title: 'Pessoas', range: [0, maxEfetivo], gridcolor: '#E8EEF0' },
        yaxis2: {
            title: { text: 'HH mensal', standoff: 18 }, overlaying: 'y', side: 'right',
            range: [0, maxHH], showgrid: false, tickformat: '~s', nticks: 6
        }
    }), CONFIG_PLOT);
}

/** Ocorrências por mês: barras agrupadas com rótulo. */
function graficoOcorrencias(elemento, dados) {
    const porMes = new Map();
    for (const r of dados) {
        const chave = +inicioDoMes(r.Data);
        if (!porMes.has(chave)) porMes.set(chave, { data: inicioDoMes(r.Data), total: 0, acidentado: 0 });
        const item = porMes.get(chave);
        item.total++;
        if (r['Com acidentado']) item.acidentado++;
    }
    const linhas = [...porMes.values()].sort((a, b) => a.data - b.data);
    const periodos = linhas.map(l => rotuloMes(l.data));
    const rotulo = v => v === 0 ? '' : String(v);

    Plotly.newPlot(elemento, [
        {
            x: periodos, y: linhas.map(l => l.total), name: 'Ocorrências', type: 'bar',
            marker: { color: VERMELHO, opacity: .97 },
            text: linhas.map(l => rotulo(l.total)), textposition: 'outside',
            textfont: { color: '#B85E67', size: 12 },
            hovertemplate: '%{x}<br>Ocorrências: %{y:.0f}<extra></extra>'
        },
        {
            x: periodos, y: linhas.map(l => l.acidentado), name: 'Com acidentado', type: 'bar',
            marker: { color: LARANJA, opacity: .97 },
            text: linhas.map(l => rotulo(l.acidentado)), textposition: 'outside',
            textfont: { color: '#A9773F', size: 12 },
            hovertemplate: '%{x}<br>Com acidentado: %{y:.0f}<extra></extra>'
        }
    ], Object.assign({}, LAYOUT_BASE, {
        height: 390, barmode: 'group',
        legend: { orientation: 'h', y: 1.12, x: 0 },
        xaxis: { title: '', tickangle: 0 },
        yaxis: { title: 'Registros', gridcolor: '#E8EEF0', dtick: 1, rangemode: 'tozero' }
    }), CONFIG_PLOT);
}

