// ---------------------------------------------------------------------------
// Carregamento
// ---------------------------------------------------------------------------

root.innerHTML = ESTILOS +
    '<div class="sms-root"><div class="sms-info">Carregando as fontes de SMS (P31 a P36)...</div></div>';

/** Equivale a _consultar_seguro: nunca lança, devolve [] quando a fonte falta. */
async function consultarSeguro(numeroPlanilha) {
    try {
        const dados = await consultar('P' + numeroPlanilha);
        return Array.isArray(dados) ? dados : [];
    } catch (err) {
        return [];
    }
}

const fontes = {};
const numeros = [31, 32, 33, 34, 35, 36];
const resultados = await Promise.all(numeros.map(consultarSeguro));
numeros.forEach((n, i) => { fontes[n] = resultados[i]; });

if (!fontes[31].length) {
    const disponiveis = await UHN.listarPlanilhas().catch(() => []);
    root.innerHTML = ESTILOS + `<div class="sms-root">
        <div class="sms-title">PAINEL EXECUTIVO DE SMS</div>
        <div class="sms-sub">P31–P36 integradas</div>
        <div class="sms-info">
          A <b>P31 — Indicadores de SMS</b> ainda não possui dados importados.<br><br>
          Este painel precisa das planilhas <b>P31</b> a <b>P36</b> na pasta do sistema.
          Use <b>Anexar</b> e depois <b>Enviar</b> no editor para carregá-las.
          <br><br><span style="font-size:.72rem;color:#687A88">
          ${disponiveis.length} planilha(s) disponível(is) hoje — nenhuma delas é a P31.</span>
        </div></div>`;
    return;
}

const p31 = prepararP31(fontes[31]);
const p32 = prepararP32(fontes[32]);
const p33 = prepararP33(fontes[33]);
const p34 = prepararP34(fontes[34]);
const p35 = prepararP35(fontes[35]);
const p36 = prepararP36(fontes[36]);

const todas = [p31, p32, p33, p34, p35, p36].filter(x => x.length);
const dataMax = new Date(Math.max(...todas.map(x => Math.max(...x.map(r => +r.Data)))));
const dataMin = new Date(Math.min(...todas.map(x => Math.min(...x.map(r => +r.Data)))));

// Lista de competências entre o menor e o maior mês (equivale a date_range freq="MS").
const competencias = [];
for (let d = new Date(Date.UTC(dataMin.getUTCFullYear(), dataMin.getUTCMonth(), 1));
     d <= dataMax;
     d = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1))) {
    competencias.push(new Date(d));
}

// ---------------------------------------------------------------------------
// Render
// ---------------------------------------------------------------------------

function renderizar(inicio, fim) {
    // O Python comparava `Data <= fim` com fim no dia 1o do mes. As fontes com
    // data real (P33) perdiam o mes inteiro: 19/06 nao e <= 01/06. Aqui o limite
    // vai ate o ultimo instante do mes escolhido, que e o que "ate 06/2026" diz.
    const fimDoMes = new Date(Date.UTC(fim.getUTCFullYear(), fim.getUTCMonth() + 1, 0, 23, 59, 59, 999));
    const filtrar = d => d.filter(r => r.Data >= inicio && r.Data <= fimDoMes);
    const a31 = filtrar(p31), a32 = filtrar(p32), a33 = filtrar(p33);
    const a34 = filtrar(p34), a36 = filtrar(p36);

    const opcoes = (selecionada) => competencias.map(c =>
        `<option value="${+c}"${+c === +selecionada ? ' selected' : ''}>${competencia(c)}</option>`).join('');

    const filtrosHtml = `<div class="sms-filtros">
        <label>Período analisado</label>
        <select id="sms-de">${opcoes(inicio)}</select>
        <span style="color:#84919B;font-size:.72rem">até</span>
        <select id="sms-ate">${opcoes(fim)}</select></div>`;

    if (!a31.length) {
        root.innerHTML = ESTILOS + `<div class="sms-root">
            <div class="sms-title">PAINEL EXECUTIVO DE SMS</div>
            ${filtrosHtml}
            <div class="sms-info">A P31 não possui indicadores no período selecionado.</div></div>`;
        ligarFiltros();
        return;
    }

    const atual = a31[a31.length - 1];
    const totalHH = soma(a31.map(r => r['HH Total']));
    const ocorrencias = a33.length;
    const acidentes = a33.length
        ? a33.filter(r => r['Com acidentado']).length
        : Math.round(soma(a31.map(r => r['Acidentados'])));
    const afastamentos = a33.length
        ? a33.filter(r => r['Com afastamento']).length
        : Math.round(soma(a31.map(r => r['Acidentes com afastamento'])));
    const diasPerdidos = soma(a31.map(r => r['Dias Perdidos']));
    const treinamento = a34.length ? soma(a34.map(r => r['Horas Treinamento'])) : 0;
    const planejadas = a34.length ? soma(a34.map(r => r['Inspeções Planejadas'])) : 0;
    const realizadas = a34.length ? soma(a34.map(r => r['Inspeções Realizadas'])) : 0;
    const atendimento = pct(realizadas, planejadas);
    const simulados = a34.length ? soma(a34.map(r => r['Simulados'])) : 0;

    const cards = [
        ['HH ACUMULADAS', fmtNum(totalHH), 'exposição no período', AZUL, null],
        ['EFETIVO ATUAL', fmtNum(atual['Efetivo Total']), 'pessoas na competência', AZUL_CLARO, null],
        ['OCORRÊNCIAS', fmtNum(ocorrencias), 'registros detalhados P33', LARANJA, null],
        ['COM ACIDENTADO', fmtNum(acidentes), 'pessoas identificadas', VERMELHO, pct(acidentes, ocorrencias)],
        ['COM AFASTAMENTO', fmtNum(afastamentos), `dias perdidos P31: ${fmtNum(diasPerdidos)}`, VERMELHO, pct(afastamentos, Math.max(acidentes, 1))],
        ['TREINAMENTO', fmtNum(treinamento), 'horas oficiais P34', VERDE, null],
        ['INSPEÇÕES', fmtPct(atendimento), `${fmtNum(realizadas)} de ${fmtNum(planejadas)}`, VERDE, atendimento],
