}

/** Religa os selects de período após cada re-render. */
function ligarFiltros() {
    const de = document.getElementById('sms-de');
    const ate = document.getElementById('sms-ate');
    if (!de || !ate) return;
    const aoMudar = () => {
        let inicio = new Date(Number(de.value));
        let fim = new Date(Number(ate.value));
        if (inicio > fim) [inicio, fim] = [fim, inicio];   // tolera inversão
        renderizar(inicio, fim);
    };
    de.addEventListener('change', aoMudar);
    ate.addEventListener('change', aoMudar);
}

