/**
 * Painel Financeiro Executivo UHN consolidado (Versão 100% JavaScript)
 * Traduzido do Python para replicar a Curva S Financeira e painéis de indicadores.
 */

async function renderizar_painel_financeiro_executivo() {
    const root = document.getElementById('dash-root');
    root.innerHTML = '<div class="flex items-center justify-center h-64 text-uhnBlue font-bold"><i class="fa-solid fa-spinner fa-spin mr-3"></i> Processando Dados Financeiros...</div>';

    // -----------------------------------------------------------------------------
    // TEMA E LIMITES
    // -----------------------------------------------------------------------------
    const AZUL_ESCURO = "#426B86", AZUL = "#5B879F", AZUL_CLARO = "#82BFD8";
    const VERDE = "#78B990", VERDE_SUAVE = "#92B26E";
    const LARANJA = "#DDA06F", AMARELO = "#E6C568", VERMELHO = "#D98189", ROXO = "#9B87C7";
    const TEXTO = "#17324D", TEXTO_SUAVE = "#66788A", FUNDO = "#F5F8FA", BORDA = "#E1E8EC";

    // -----------------------------------------------------------------------------
    // FUNÇÕES DE APOIO
    // -----------------------------------------------------------------------------
    function parseNum(val) {
        if (val === null || val === undefined || val === '') return NaN;
        if (typeof val === 'number') return val;
        let s = String(val).trim().replace(/[R$€%]/g, '').trim();
        if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
        else if (s.includes(',')) s = s.replace(',', '.');
        return parseFloat(s);
    }

    function parseDataStr(val) {
        if (!val) return null;
        let d = new Date(val);
        if (typeof val === 'number') d = new Date(Math.round((val - 25569)*86400*1000));
        if (isNaN(d.getTime())) return null;
        return d;
    }

    function fmtMoeda(valor, sinal=false) {
        if (isNaN(valor) || valor === null) return "—";
        let num = Math.abs(valor);
        let prefixo = (sinal && valor > 0) ? "+" : "";
        let s = num.toFixed(1).replace('.', ',');
        return valor < 0 ? `-R$ ${s} MM` : `${prefixo}R$ ${s} MM`;
    }

    function fmtPct(valor, sinal=false) {
        if (isNaN(valor) || valor === null) return "—";
        let prefixo = (sinal && valor > 0) ? "+" : "";
        let num = valor * 100;
        let s = Math.abs(num).toFixed(1).replace('.', ',');
        return valor < 0 ? `-${s}%` : `${prefixo}${s}%`;
    }

    function dataRotulo(d, sem) {
        if (d) {
            const meses = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
            return `${meses[d.getUTCMonth()]}/${d.getUTCFullYear()}`;
        }
        return `Semana ${sem}`;
    }

    function escapeHTML(str) {
        if (!str) return "";
        return String(str).replace(/[&<>'"]/g, tag => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;'
        }[tag]));
    }

    function findCol(row, keys) {
        let r = Object.keys(row).find(k => keys.some(key => k.toLowerCase() === key.toLowerCase()));
        return r;
    }

    const _icone_svg = (nome) => {
        const caminhos = {
            "alerta": '<path d="M12 3 2.8 20h18.4L12 3Z"/><path d="M12 9v5"/><path d="M12 17.5h.01"/>',
            "positivo": '<circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16.5 8.5"/>',
            "saldo": '<circle cx="12" cy="12" r="9"/><path d="M15.5 8.5c-.8-.7-1.9-1-3-1-1.7 0-3 .8-3 2s1 1.8 3 2.3 3 1 3 2.4-1.3 2.3-3 2.3c-1.3 0-2.5-.4-3.4-1.2M12 5.5v13"/>',
            "alta": '<path d="M4 17 10 11l4 4 6-8"/><path d="M15 7h5v5"/>',
            "baixa": '<path d="m4 7 6 6 4-4 6 8"/><path d="M15 17h5v-5"/>',
            "media": '<path d="M4 16V9M10 16V5M16 16v-7M22 16V3"/><path d="M3 20h19"/>',
            "pico": '<path d="M3 18 8 12l4 3 5-9 4 4"/><path d="M17 6h4v4"/>',
        };
        return `<svg viewBox="0 0 24 24" aria-hidden="true">${caminhos[nome]}</svg>`;
    };

    // -----------------------------------------------------------------------------
    // CARREGAMENTO DE DADOS
    // -----------------------------------------------------------------------------
    let p22, p21, p39, p40, p41, p42, p43;
    try {
        [p22, p21, p39, p40, p41, p42, p43] = await Promise.all([
            consultar('SELECT * FROM "planilha_22"'),
            consultar('SELECT * FROM "planilha_21"'),
            consultar('SELECT * FROM "planilha_39"'),
            consultar('SELECT * FROM "planilha_40"'),
            consultar('SELECT * FROM "planilha_41"'),
            consultar('SELECT * FROM "planilha_42"'),
            consultar('SELECT * FROM "planilha_43"')
