    }

    if (!p22 || p22.length === 0) {
        root.innerHTML = '<div class="bg-blue-50 text-blue-700 p-4 rounded">A P22 — Curva S Financeira não possui períodos válidos.</div>';
        return;
    }

    // Identificar colunas P22
    let base_p22 = p22[0];
    let col_data = findCol(base_p22, ["data", "data_semana", "data_da_semana", "periodo", "mes", "numero_semana"]);
    let col_sem = findCol(base_p22, ["semana", "numero_da_semana", "n_semana", "numero_semana"]);
    let col_plan_acum = findCol(base_p22, ["previsto_lb_acum", "planejado_acum"]);
    let col_real_acum = findCol(base_p22, ["realizado_acum"]);
    let col_proj_acum = findCol(base_p22, ["projetado_acum", "forecast_acum"]);
    let col_plan_mes = findCol(base_p22, ["previsto_lb", "planejado_mensal"]);
    let col_real_mes = findCol(base_p22, ["realizado", "realizado_mensal"]);
    let col_proj_mes = findCol(base_p22, ["projetado", "forecast_mensal"]);

    if (!col_plan_acum || !col_real_acum) {
        root.innerHTML = '<div class="bg-red-50 text-red-700 p-4 rounded">P22: campos essenciais (planejado/realizado acumulado) não encontrados.</div>';
