    }
    if (mensal.length > 0) {
        let ultimos = mensal.slice(-3);
        media3 = ultimos.reduce((s,c) => s+c.RealizadoMensal,0)/ultimos.length;
        pico = Math.max(...mensal.map(m=>m.RealizadoMensal));
    }

    // Fisico Complementar (P39-P43)
    let tabelasFisicas = [
        {df: p39, num: 39, nome: "Suprimentos"}, {df: p40, num: 40, nome: "Reparo e Inspeção"},
