/**
 * Controle de Juntas — PIPE × CAMPO por diâmetro. Fonte: Planilha 02.
 * ---------------------------------------------------------------------------
 * Conversão do painel Streamlit/pandas para JavaScript:
 *   st.columns / st.markdown -> HTML + CSS (o CSS original foi preservado)
 *   pandas.crosstab          -> agregação manual em Map
 *   st.segmented_control     -> botões que re-renderizam a tabela cruzada
 *
 * Escala térmica igual à do painel de SOP: vermelho nos estágios iniciais,
 * amarelo no meio, verde na conclusão.
 */

const root = document.getElementById('dash-root');

const ORDEM_STATUS = [
    'Não Iniciada',
    'Aguardando Rastreabilidade de Material',
    'Aguardando Soldagem',
    'Soldada sem VA',
    'Aguardando Exame Visual',
    'Aguardando Visual de Ajuste',
    'Aguardando RX/US - Pré-TT',
    'Aguardando LP/PM - Pré-TT',
    'Aguardando Tratamento Termico',
    'Aguardando RX/US',
    'Aguardando LP/PM',
    'Aguardando Liberação Lote LP/PM',
    'Aguardando Dureza',
    'Aguardando Identificação de Liga do Metal de Adição',
    'Aguardando Reparo de Solda',
    'Aguardando Visual de Reparo',
    'Aguardando RX/US Reparo',
    'Aguardando LP/PM - Acabamento Reparo',
    'Junta Liberada'
];

const AZUL = '#5B879F';
const VERDE = '#78B990';
const LARANJA = '#DDA06F';
const ROXO = '#9B87C7';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Equivale a _normalizar: sem acento, minúsculo, não-alfanumérico vira "_". */
function normalizar(valor) {
    const texto = String(valor === null || valor === undefined ? '' : valor)
        .normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase();
    return texto.replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

/** Equivale a _coluna: acha a coluna real a partir de nomes candidatos. */
function coluna(linhas, ...candidatos) {
    if (!linhas.length) return null;
    const existentes = new Map();
    for (const chave of Object.keys(linhas[0])) existentes.set(normalizar(chave), chave);
    for (const candidato of candidatos) {
        const n = normalizar(candidato);
        if (existentes.has(n)) return existentes.get(n);
    }
    return null;
}

/** Converte textos como 1 1/2" em valor numérico, para ordenar os diâmetros. */
function valorDiametro(valor) {
    const texto = String(valor === null || valor === undefined ? '' : valor).replace(/"/g, '').trim();
    if (!texto) return 9999;
    let total = 0;
    for (const parte of texto.split(/\s+/)) {
        if (parte.includes('/')) {
            const [a, b] = parte.split('/');
            const na = parseFloat(a), nb = parseFloat(b);
            if (!isFinite(na) || !isFinite(nb) || nb === 0) return 9999;
            total += na / nb;
        } else {
            const n = parseFloat(parte.replace(',', '.'));
            if (!isFinite(n)) return 9999;
            total += n;
        }
    }
    return total;
}

/** Escala do painel SOP: 0% vermelho, 50% amarelo, 100% verde. */
function corPercentual(valor) {
    const v = Math.max(0, Math.min(100, Number(valor) || 0));
    return 'hsl(' + Math.round(v * 1.2) + ', 62%, 46%)';
}

/** Cores de linha da matriz: primeiro status vermelho, último verde. */
function corStatus(indice, total) {
    const fracao = indice / Math.max(total - 1, 1);
    const matiz = Math.round(120 * fracao);
    return ['hsl(' + matiz + ', 78%, 94%)', 'hsl(' + matiz + ', 66%, 43%)'];
}

function fmtNum(valor) {
    return Math.round(Number(valor) || 0).toLocaleString('pt-BR');
}

function fmtPct(valor) {
    return (Number(valor) || 0).toFixed(1).replace('.', ',') + '%';
}

function escapar(valor) {
    return String(valor === null || valor === undefined ? '' : valor)
        .replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function texto(valor, padrao) {
    if (valor === null || valor === undefined) return padrao;
    const s = String(valor).trim();
    return s === '' ? padrao : s;
}

// ---------------------------------------------------------------------------
// Preparação
// ---------------------------------------------------------------------------

/** Normaliza a Planilha 02 e calcula Previsto, Executado e A executar. */
function prepararJuntas(dados) {
    if (!dados || !dados.length) return [];

    const cols = {
        tipo: coluna(dados, 'primeira_solda/pip_shop', 'primeira_solda_pip_shop', 'tipo_junta', 'local_solda', 'pipe_campo'),
        diametro: coluna(dados, 'diametro', 'diâmetro', 'diametro_junta'),
        status: coluna(dados, 'status_Tubulacao_juntas', 'status_tubulacao_juntas', 'status_junta', 'status'),
        tipoSolda: coluna(dados, 'tipo_de_solda', 'tipo_solda', 'tipo de solda'),
        unidade: coluna(dados, 'unidade'),
        secao: coluna(dados, 'secao', 'seção'),
        spool: coluna(dados, 'Spool', 'spool'),
        junta: coluna(dados, 'juntas', 'junta')
    };

    const faltantes = ['tipo', 'diametro', 'status', 'tipoSolda'].filter(n => cols[n] === null);
    if (faltantes.length) {
        throw new Error('Planilha 02: campos obrigatórios não reconhecidos (' + faltantes.join(', ') + '). ' +
            'Campos disponíveis: ' + Object.keys(dados[0] || {}).join(', '));
    }

    const saida = [];
    for (let i = 0; i < dados.length; i++) {
        const linha = dados[i];

        let tipo = texto(linha[cols.tipo], '').toUpperCase();
        if (tipo === 'PIP' || tipo === 'SHOP') tipo = 'PIPE';
        if (tipo === 'CAMPO ') tipo = 'CAMPO';

        const tipoSolda = texto(linha[cols.tipoSolda], '').toUpperCase();

        // SU identifica soldagem de suportes: não integra os indicadores de
        // juntas de processo deste painel.
        if ((tipo !== 'PIPE' && tipo !== 'CAMPO') || tipoSolda === 'SU') continue;

        const status = texto(linha[cols.status], 'Não informado');
        const executado = normalizar(status) === 'junta_liberada' ? 1 : 0;

        saida.push({
            Tipo: tipo,
            'Diâmetro': texto(linha[cols.diametro], 'Não informado'),
            Status: status,
            'Tipo de solda': tipoSolda,
            Unidade: cols.unidade ? texto(linha[cols.unidade], 'Não informada') : 'Não informada',
            'Seção': cols.secao ? texto(linha[cols.secao], 'Não informada') : 'Não informada',
            Spool: cols.spool ? texto(linha[cols.spool], 'Não informado') : 'Não informado',
            Junta: cols.junta ? texto(linha[cols.junta], 'Não informada') : String(i),
            Previsto: 1,
            Executado: executado,
            'A executar': 1 - executado
        });
    }
    return saida;
}

/** Agrupa por diâmetro, somando Previsto/Executado/A executar. */
function resumoPorDiametro(base) {
    const mapa = new Map();
    for (const l of base) {
        const d = l['Diâmetro'];
        if (!mapa.has(d)) mapa.set(d, { 'Diâmetro': d, Previsto: 0, Executado: 0, 'A executar': 0 });
        const item = mapa.get(d);
        item.Previsto += l.Previsto;
        item.Executado += l.Executado;
        item['A executar'] += l['A executar'];
    }
    const lista = [...mapa.values()];
    lista.forEach(r => { r['Avanço (%)'] = r.Previsto ? (r.Executado / r.Previsto) * 100 : 0; });
    lista.sort((a, b) => {
        const va = valorDiametro(a['Diâmetro']), vb = valorDiametro(b['Diâmetro']);
        return va !== vb ? va - vb : String(a['Diâmetro']).localeCompare(String(b['Diâmetro']));
    });
    return lista;
}

function metricas(grupo) {
    const previsto = grupo.reduce((s, l) => s + l.Previsto, 0);
    const executado = grupo.reduce((s, l) => s + l.Executado, 0);
    const saldo = grupo.reduce((s, l) => s + l['A executar'], 0);
    return { previsto, executado, saldo, avanco: previsto ? (executado / previsto) * 100 : 0 };
}

/** Cruza status nas linhas e diâmetros nas colunas, na ordem gerencial. */
function tabelaCruzada(base) {
    const diametros = [...new Set(base.map(l => l['Diâmetro']))].sort((a, b) => {
        const va = valorDiametro(a), vb = valorDiametro(b);
        return va !== vb ? va - vb : String(a).localeCompare(String(b));
    });

    const canonicos = new Map(ORDEM_STATUS.map(s => [normalizar(s), s]));
    const contagem = new Map();
    let temOutros = false;

    for (const l of base) {
        const canonico = canonicos.get(normalizar(l.Status)) || 'Outros status';
        if (canonico === 'Outros status') temOutros = true;
        if (!contagem.has(canonico)) contagem.set(canonico, new Map());
        const linha = contagem.get(canonico);
        linha.set(l['Diâmetro'], (linha.get(l['Diâmetro']) || 0) + 1);
    }

    const ordemLinhas = ORDEM_STATUS.slice();
    if (temOutros) ordemLinhas.push('Outros status');

    const matriz = ordemLinhas.map(status => {
        const linha = contagem.get(status) || new Map();
        const valores = diametros.map(d => linha.get(d) || 0);
        return { status, valores, total: valores.reduce((a, b) => a + b, 0) };
    });

    const totais = diametros.map((_, i) => matriz.reduce((s, l) => s + l.valores[i], 0));
    return {
        diametros,
        linhas: matriz,
        total: { valores: totais, total: totais.reduce((a, b) => a + b, 0) }
    };
}

