    }).join('');

    return '<div class="jd-table-wrap"><table class="jd-table"><thead><tr>' +
        '<th>Ø</th><th>Prev.</th><th>Exec.</th><th>Saldo</th><th>Avanço</th>' +
        '</tr></thead><tbody>' + linhas + '</tbody></table></div>';
}

/** Insights por diâmetro; rankings percentuais exigem 10+ juntas. */
function insightsHtml(tabela, titulo, cor) {
    const base = tabela.filter(r => String(r['Diâmetro']).toUpperCase() !== 'TOTAL');
    if (!base.length) {
        return `<div class="jd-insight" style="--cor:${cor}"><div class="jd-insight-title">${titulo}</div>Sem dados.</div>`;
    }

    const maiorPor = (campo) => base.reduce((a, b) => (b[campo] > a[campo] ? b : a));
    const maiorSaldo = maiorPor('A executar');
    const maiorExec = maiorPor('Executado');

    let elegiveis = base.filter(r => r.Previsto >= 10);
    if (!elegiveis.length) elegiveis = base;
    const melhor = elegiveis.reduce((a, b) => (b['Avanço (%)'] > a['Avanço (%)'] ? b : a));
    const menor = elegiveis.reduce((a, b) => (b['Avanço (%)'] < a['Avanço (%)'] ? b : a));

    const previsto = base.reduce((s, r) => s + r.Previsto, 0);
    const executado = base.reduce((s, r) => s + r.Executado, 0);
    const avanco = previsto ? (executado / previsto) * 100 : 0;

    const linha = (icone, rotulo, valor) =>
        `<div class="jd-insight-row"><div class="jd-insight-icon">${icone}</div><div>` +
        `<div class="jd-insight-label">${rotulo}</div><div class="jd-insight-value">${valor}</div></div></div>`;

    return `<div class="jd-insight" style="--cor:${cor}">
      <div class="jd-insight-title">INSIGHTS — ${titulo}</div>
      ${linha('⚠️', 'Maior saldo pendente', escapar(maiorSaldo['Diâmetro']) + ' — ' + fmtNum(maiorSaldo['A executar']) + ' juntas')}
      ${linha('✅', 'Maior volume executado', escapar(maiorExec['Diâmetro']) + ' — ' + fmtNum(maiorExec.Executado) + ' juntas')}
      ${linha('↗', 'Melhor avanço (mín. 10 juntas)', escapar(melhor['Diâmetro']) + ' — ' + fmtPct(melhor['Avanço (%)']))}
      ${linha('↘', 'Menor avanço (mín. 10 juntas)', escapar(menor['Diâmetro']) + ' — ' + fmtPct(menor['Avanço (%)']))}
      <div class="jd-insight-status">Avanço da categoria:
        <span style="color:${corPercentual(avanco)}">${fmtPct(avanco)}</span></div>
    </div>`;
}

/** Matriz com temperatura por evolução do status, igual ao painel SOP. */
function tabelaCruzadaHtml(cruzada) {
    const cabecalho = cruzada.diametros.map(d => `<th>${escapar(d)}</th>`).join('') + '<th>TOTAL</th>';
    const semOutros = cruzada.linhas.filter(l => l.status !== 'Outros status').length;

    const corpo = cruzada.linhas.map((linha, indice) => {
        let classe, estilo;
        if (linha.status === 'Outros status') {
            classe = ' class="jd-temp-row jd-outros-status"';
            estilo = ' style="--temp-bg:#F1F4F5;--temp-strong:#8C9AA3"';
        } else {
            const [fundo, forte] = corStatus(indice, semOutros);
            classe = ' class="jd-temp-row"';
            estilo = ` style="--temp-bg:${fundo};--temp-strong:${forte}"`;
        }
        const celulas = linha.valores.concat([linha.total])
            .map(v => `<td class="${v === 0 ? 'jd-cross-zero' : 'jd-cross-value'}">${fmtNum(v)}</td>`).join('');
        return `<tr${classe}${estilo}><th>${escapar(linha.status)}</th>${celulas}</tr>`;
    }).join('');

    const totais = cruzada.total.valores.concat([cruzada.total.total])
        .map(v => `<td class="${v === 0 ? 'jd-cross-zero' : 'jd-cross-value'}">${fmtNum(v)}</td>`).join('');

    return '<div class="jd-cross-wrap"><table class="jd-cross"><thead><tr><th>Status da junta</th>' +
        cabecalho + '</tr></thead><tbody>' + corpo +
        `<tr class="jd-cross-total"><th>TOTAL</th>${totais}</tr>` +
        '</tbody></table></div>';
}

