/**
 * Dashboard Executivo de Suprimentos — alimentado pela base SUP_DETALHADO.
 * ---------------------------------------------------------------------------
 * Conversão do painel Streamlit/pandas/Altair/DuckDB para JavaScript:
 *   DuckDB (EXTERNAL_DB_PATH)  -> consultar() tentando os mesmos nomes de tabela
 *   st.tabs                    -> barra de abas própria (.sup-tab), com conteúdo
 *                                  recriado a cada troca de aba ou de filtro
 *   st.multiselect              -> dropdown de checkboxes com busca (criarMultiSelect)
 *   st.date_input (intervalo)   -> dois <input type="date">
 *   Altair                      -> Plotly (já carregado no sandbox)
 *   pandas.DataFrame            -> arrays de objetos simples (records)
 *
 * O painel trabalha com CONTAGEM de linhas/códigos, nunca soma de quantidade
 * física, porque a base mistura unidades heterogêneas (pç, un, m, m², kg, kit
 * e conjunto) — mesma premissa do original.
 *
 * Como usar: selecione a planilha de suprimentos no seletor do editor (ela
 * aparecerá em `dados.SUP_DETALHADO` ou `dados.P30`) OU deixe sem selecionar —
 * o painel tenta `consultar()` nos mesmos nomes que o Python tentava no DuckDB.
 */

const root = document.getElementById('dash-root');

// ---------------------------------------------------------------------------
// Constantes
// ---------------------------------------------------------------------------

const STATUS_ORDEM = [
    '01-Aguardando Cotação',
    '02-Aguardando Compra',
