    [STATUS_ORDEM[2]]: 'Aguard. Lib. Fornecedor',
    [STATUS_ORDEM[3]]: 'Aguard. Lib. Transporte',
    [STATUS_ORDEM[4]]: 'Em Transporte',
    [STATUS_ORDEM[5]]: 'Recebido',
    [STATUS_ORDEM[6]]: 'Fornec. Petrobras'
};

// Para gestão, material fornecido pela Petrobras não representa pendência:
// é consolidado na mesma etapa dos materiais recebidos no canteiro.
const STATUS_PAINEL_ORDEM = STATUS_ORDEM.slice(0, 6);
const STATUS_PAINEL_CURTO = Object.assign({}, STATUS_CURTO, { [STATUS_ORDEM[5]]: 'Recebido' });

const DISCIPLINA_CURTA = {
    'Equipamentos Mecânicos - Dinâmicos': 'Equip. Mec. Dinâmicos',
    'Equipamentos Mecânicos - Estáticos': 'Equip. Mec. Estáticos',
    'Equipamentos Elétricos': 'Equip. Elétricos',
    'Estrutura Metálica': 'Estrut. Metálica',
    'Instrumentação': 'Instrument.'
};
function disciplinaCurta(valor) { return DISCIPLINA_CURTA[valor] || valor; }

const CORES = {
    azul: '#6F9FBE', azul2: '#79B7D8', verde: '#78B990',
    amarelo: '#E6C568', vermelho: '#D98189', roxo: '#9B87C7', cinza: '#8D9BA5'
};

// ---------------------------------------------------------------------------
// Helpers de texto, número e data
// ---------------------------------------------------------------------------

function normalizar(valor) {
    return String(valor === null || valor === undefined ? '' : valor)
        .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
        .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

/** Acha a coluna real a partir de nomes candidatos, tolerando variação de grafia. */
function coluna(linhas, ...candidatos) {
    if (!linhas.length) return null;
    const existentes = new Map();
    for (const chave of Object.keys(linhas[0])) existentes.set(normalizar(chave), chave);
    for (const candidato of candidatos) {
        const n = normalizar(candidato);
        if (existentes.has(n)) return existentes.get(n);
    }
    return null;
}

function texto(valor, padrao) {
    padrao = padrao === undefined ? 'Não informado' : padrao;
    if (valor === null || valor === undefined) return padrao;
    const s = String(valor).trim();
    return (s === '' || s === 'nan' || s === 'None' || s === '<NA>' || s === '...') ? padrao : s;
}

function numero(valor) {
    if (valor === null || valor === undefined || valor === '') return null;
    let n;
    if (typeof valor === 'number') n = valor;
    else n = parseFloat(String(valor).trim().replace(/\s/g, '').replace(',', '.'));
    if (!isFinite(n)) return null;
    // Bloqueia valores evidentemente corrompidos pela conversão do arquivo legado.
    return Math.abs(n) > 1000000000 ? null : n;
}

/** Aceita Date, serial do Excel, dd/mm/aaaa ou aaaa-mm-dd. */
function paraData(valor) {
    if (valor === null || valor === undefined || valor === '') return null;
    if (valor instanceof Date) return isNaN(valor.getTime()) ? null : valor;
    if (typeof valor === 'number') {
        const d = new Date(Math.round((valor - 25569) * 86400 * 1000));
        return isNaN(d.getTime()) ? null : d;
    }
    const s = String(valor).trim();
    const br = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
    if (br) {
        let ano = parseInt(br[3], 10);
        if (br[3].length === 2) ano += 2000;
        return new Date(Date.UTC(ano, parseInt(br[2], 10) - 1, parseInt(br[1], 10)));
    }
    const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (iso) return new Date(Date.UTC(+iso[1], +iso[2] - 1, +iso[3]));
    const d = new Date(s);
    return isNaN(d.getTime()) ? null : d;
}

function dataSomenteData(d) { return new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate())); }
function diffDias(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }

function mediana(valores) {
    if (!valores.length) return 0;
    const v = valores.slice().sort((a, b) => a - b);
    const meio = Math.floor(v.length / 2);
    return v.length % 2 ? v[meio] : (v[meio - 1] + v[meio]) / 2;
}

function fmtNum(valor) {
    const n = Math.round(Number(valor));
    return isFinite(n) ? n.toLocaleString('pt-BR') : '0';
}
function fmtPct(valor) {
    const n = Number(valor);
    return isFinite(n) ? n.toFixed(1).replace('.', ',') + '%' : '0,0%';
}
function escapar(valor) {
    return String(valor === null || valor === undefined ? '' : valor)
        .replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function formatarDataBR(d) {
    return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0') + '/' + d.getUTCFullYear();
}
function paraISO(d) {
    if (!d) return '';
    return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
}
const MESES_ABREV = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
function rotuloMes(d) { return MESES_ABREV[d.getUTCMonth()] + '/' + String(d.getUTCFullYear()).slice(-2); }
function acumular(arr) { let s = 0; return arr.map(v => s += v); }

// ---------------------------------------------------------------------------
// Busca de dados
// ---------------------------------------------------------------------------

/** Tenta os mesmos nomes que o Python tentava no DuckDB, na mesma ordem. */
async function buscarBase() {
    if (typeof dados !== 'undefined' && dados) {
        for (const chave of ['SUP_DETALHADO', 'Sup_detalhado', 'sup_detalhado', 'P30']) {
            if (Array.isArray(dados[chave]) && dados[chave].length) return { linhas: dados[chave], origem: chave };
        }
    }
    const candidatos = ['SUP_DETALHADO', 'sup_detalhado', 'planilha_sup_detalhado', 'P30'];
    for (const nome of candidatos) {
        try {
            const linhas = await consultar(nome);
            if (linhas && linhas.length) return { linhas, origem: nome };
        } catch (err) { /* tenta o proximo nome */ }
    }
    return { linhas: [], origem: null };
}

