/** Saneia a base e cria as métricas por registro (equivalente a preparar_suprimentos). */
function prepararSuprimentos(linhasBrutas, dataCorteInput) {
    if (!linhasBrutas || !linhasBrutas.length) return [];

    // "diciplina" é o nome com que a coluna às vezes chega na fonte (typo
    // legado); o alias garante que "disciplina" resolva mesmo assim.
    const colDisciplina = coluna(linhasBrutas, 'disciplina', 'diciplina');
    const colCodigo = coluna(linhasBrutas, 'codigo');
    const colDescricaoMaterial = coluna(linhasBrutas, 'descricao_do_material', 'descricao_material');
    const colUnidMedida = coluna(linhasBrutas, 'unid_medida', 'unidade_medida');
    const colRM = coluna(linhasBrutas, 'rm_engenharia');
    const colPO = coluna(linhasBrutas, 'numero_da_po');
    const colFornecedor = coluna(linhasBrutas, 'fornecedor');
    const colDescricaoAF = coluna(linhasBrutas, 'descricao_da_af');
    const colSituacao = coluna(linhasBrutas, 'situacao_do_processo', 'situacao');
    const colTagueado = coluna(linhasBrutas, 'item_tagueado');
    const colDataEmissao = coluna(linhasBrutas, 'data_de_emissao');
    const colPrevEntregaObra = coluna(linhasBrutas, 'dt_prev_entrega_obra');
    const colChegadaNem = coluna(linhasBrutas, 'data_de_chegada_nem', 'data_chegada');

    // Mantém somente registros que representam itens do fluxo de suprimentos.
    // O prefixo 01–07 é a assinatura mais segura de uma linha válida nesta
    // fonte; o fallback por RM preenchida mantém compatibilidade quando a
    // situação não vier codificada.
    const comStatus = colSituacao
        ? linhasBrutas.filter(l => { const v = l[colSituacao]; return typeof v === 'string' && /^0[1-7]-/.test(v.trim()); })
        : [];
    const selecionadas = comStatus.length ? comStatus
        : (colRM ? linhasBrutas.filter(l => l[colRM] !== null && l[colRM] !== undefined && String(l[colRM]).trim() !== '') : []);

    const corte = dataCorteInput ? dataSomenteData(new Date(dataCorteInput)) : dataSomenteData(new Date());
    const registros = [];

    for (const l of selecionadas) {
        const disciplina = texto(colDisciplina ? l[colDisciplina] : null);
        const codigo = texto(colCodigo ? l[colCodigo] : null);
        const descricaoMaterial = texto(colDescricaoMaterial ? l[colDescricaoMaterial] : null);
        const unidMedida = texto(colUnidMedida ? l[colUnidMedida] : null);
        const rm = texto(colRM ? l[colRM] : null);
        const po = texto(colPO ? l[colPO] : null);
        const fornecedor = texto(colFornecedor ? l[colFornecedor] : null);
        const descricaoAF = texto(colDescricaoAF ? l[colDescricaoAF] : null);
        const situacao = texto(colSituacao ? l[colSituacao] : null);
        const tagueado = texto(colTagueado ? l[colTagueado] : null);

        const dataEmissao = paraData(colDataEmissao ? l[colDataEmissao] : null);
        const prevEntregaObra = paraData(colPrevEntregaObra ? l[colPrevEntregaObra] : null);
        const chegadaNem = paraData(colChegadaNem ? l[colChegadaNem] : null);

        const recebido = chegadaNem !== null || STATUS_ORDEM.slice(5).includes(situacao);
        const etapaPainel = situacao === STATUS_ORDEM[6] ? STATUS_ORDEM[5] : situacao;
        const vencido = !recebido && prevEntregaObra !== null && prevEntregaObra.getTime() < corte.getTime();
        const semPO = po === 'Não informado';
        const semPrevisao = !recebido && prevEntregaObra === null;
        const naoTagueado = tagueado.toUpperCase() !== 'TAGUEADO';

        // Nulo quando não há previsão (equivalente ao NaN do pandas): mantém
        // essas linhas fora de médias e histogramas de atraso, em vez de
        // tratá-las como "0 dias de atraso" — que seria um viés otimista.
        const diasAtraso = prevEntregaObra !== null ? Math.max(0, diffDias(corte, prevEntregaObra)) : null;
        const desvioChegada = (chegadaNem !== null && prevEntregaObra !== null) ? diffDias(chegadaNem, prevEntregaObra) : null;
        const aging = dataEmissao !== null ? Math.max(0, diffDias(corte, dataEmissao)) : null;
        const noPrazo = chegadaNem !== null && prevEntregaObra !== null && chegadaNem.getTime() <= prevEntregaObra.getTime();

        let score = 0;
        if (vencido) score += 5;
        if (semPrevisao) score += 3;
        if (semPO) score += 2;
        if (naoTagueado) score += 1;
        if (diasAtraso !== null && diasAtraso >= 30) score += 2;
        if (diasAtraso !== null && diasAtraso >= 90) score += 2;

        let criticidade;
        if (score <= 2) criticidade = 'Baixo';
        else if (score <= 5) criticidade = 'Moderado';
        else if (score <= 8) criticidade = 'Alto';
        else criticidade = 'Crítico';

        registros.push({
            Disciplina: disciplina, Codigo: codigo, DescricaoMaterial: descricaoMaterial, UnidMedida: unidMedida,
            RM: rm, PO: po, Fornecedor: fornecedor, DescricaoAF: descricaoAF, Situacao: situacao, Tagueado: tagueado,
            DataEmissao: dataEmissao, DataEntregaProjeto: prevEntregaObra, ChegadaNem: chegadaNem,
            Recebido: recebido, EtapaPainel: etapaPainel, Vencido: vencido, SemPO: semPO,
            SemPrevisao: semPrevisao, NaoTagueado: naoTagueado, DiasAtraso: diasAtraso,
            DesvioChegada: desvioChegada, Aging: aging, NoPrazo: noPrazo,
            ScoreRisco: score, Criticidade: criticidade, DataCorte: corte
        });
    }
    return registros;
}

