function cardHtml(titulo, valor, meta, variacao, cor, progresso, tendencia) {
    const p = Math.max(0, Math.min(100, Number(progresso) || 0));
    return '<div class="sup-card" style="--cor:' + cor + '">' +
        '<div class="sup-card-top"><span>' + escapar(titulo) + '</span><i>' + (tendencia || '\u2192') + '</i></div>' +
        '<div class="sup-value">' + escapar(valor) + '</div>' +
        '<div class="sup-card-meta"><span>Meta: ' + escapar(meta) + '</span><b>' + escapar(variacao) + '</b></div>' +
        '<div class="sup-track"><i style="width:' + p.toFixed(1) + '%"></i></div>' +
        '</div>';
}

function bandHtml(titulo, subtitulo) {
    return '<div class="sup-band"><b>' + escapar(titulo) + '</b>' +
        (subtitulo ? '<span>' + escapar(subtitulo) + '</span>' : '') + '</div>';
}

function premissaEmHtml(container, texto) {
    const div = document.createElement('div');
    div.className = 'sup-premissa';
    div.innerHTML = '<b>Premissa:</b> ' + escapar(texto);
    container.appendChild(div);
}

function insightHtml(titulo, texto, cor, icone) {
    return '<div class="sup-insight" style="--cor:' + cor + '"><i>' + icone + '</i><div>' +
        '<b>' + escapar(titulo) + '</b><span>' + escapar(texto) + '</span></div></div>';
}

// Só estas cinco colunas ficam alinhadas à esquerda como texto; o restante
// (RM, PO, Código, datas, scores...) fica centralizado como se fosse número,
// mesmo critério do painel original.
const COLUNAS_TEXTO = new Set(['Material', 'Fornecedor', 'Descrição', 'Situação', 'Disciplina']);

/** Renderiza tabela em largura fixa, sem rolagem horizontal (equivalente a _tabela_compacta). */
function tabelaCompactaHtml(linhas, colunas, larguras, percentuais, maxLinhas) {
    percentuais = new Set(percentuais || []);
    const dados = maxLinhas ? linhas.slice(0, maxLinhas) : linhas;
    const colgroup = colunas.map(c =>
        '<col style="width:' + (Number((larguras || {})[c]) || (100 / colunas.length)).toFixed(2) + '%">').join('');
    const cabecalho = colunas.map(c => '<th>' + escapar(c) + '</th>').join('');

    const corpo = dados.map(registro => {
        const celulas = colunas.map(c => {
            const valor = registro[c];
            if (percentuais.has(c)) {
                const pct = Math.max(0, Math.min(100, Number(valor) || 0));
                const cor = pct >= 90 ? CORES.verde : pct >= 70 ? CORES.amarelo : CORES.vermelho;
                return '<td class="sup-num"><div class="sup-pct"><span><i style="width:' + pct.toFixed(1) +
                    '%;background:' + cor + '"></i></span><b>' + escapar(fmtPct(pct)) + '</b></div></td>';
            }
            let exibido;
            if (valor === null || valor === undefined || valor === 'nan' || valor === '<NA>') exibido = '\u2014';
            else if (typeof valor === 'number') exibido = fmtNum(valor);
            else exibido = String(valor);
            const classe = COLUNAS_TEXTO.has(c) ? 'sup-text' : 'sup-num';
            return '<td class="' + classe + '" title="' + escapar(exibido) + '">' + escapar(exibido) + '</td>';
        }).join('');
        return '<tr>' + celulas + '</tr>';
    }).join('');

    return '<div class="sup-table-box"><table class="sup-table"><colgroup>' + colgroup + '</colgroup>' +
        '<thead><tr>' + cabecalho + '</tr></thead><tbody>' + corpo + '</tbody></table></div>';
}

