// Agregações
// ---------------------------------------------------------------------------

/** Consolida desempenho de entrega por dimensão, sem misturar unidades físicas. */
function resumoEntregas(base, obterDimensao) {
    const grupos = new Map();
    for (const r of base) {
        const chave = obterDimensao(r);
        if (!grupos.has(chave)) grupos.set(chave, {
            dimensao: chave, codigos: new Set(), rms: new Set(), pos: new Set(),
            linhas: 0, recebidos: 0, vencidos: 0, semPrevisao: 0, noPrazo: 0, comparaveis: 0
        });
        const g = grupos.get(chave);
        g.linhas++;
        g.codigos.add(r.Codigo);
        g.rms.add(r.RM);
        g.pos.add(r.PO);
        if (r.Recebido) g.recebidos++;
        if (r.Vencido) g.vencidos++;
        if (r.SemPrevisao) g.semPrevisao++;
        if (r.ChegadaNem !== null && r.DataEntregaProjeto !== null) {
            g.comparaveis++;
            if (r.NoPrazo) g.noPrazo++;
        }
    }
    return [...grupos.values()].map(g => ({
        dimensao: g.dimensao, Linhas: g.linhas, Codigos: g.codigos.size, RMs: g.rms.size, POs: g.pos.size,
        Recebidos: g.recebidos, Vencidos: g.vencidos, SemPrevisao: g.semPrevisao, Comparaveis: g.comparaveis,
        RecebimentoPct: g.linhas ? (g.recebidos / g.linhas) * 100 : 0,
        AderenciaPct: g.comparaveis ? (g.noPrazo / g.comparaveis) * 100 : 0
    }));
}

