function renderTimeline(container, base) {
    function bucketMes(data) { return new Date(Date.UTC(data.getUTCFullYear(), data.getUTCMonth(), 1)); }
    function serieMensal(campo) {
        const mapa = new Map();
        for (const r of base) {
            const d = r[campo];
            if (!d) continue;
            const chave = +bucketMes(d);
            mapa.set(chave, (mapa.get(chave) || 0) + 1);
        }
        return mapa;
    }
    const previsto = serieMensal('DataEntregaProjeto');
    const chegada = serieMensal('ChegadaNem');

    if (!previsto.size && !chegada.size) {
        container.innerHTML = '<div class="sup-info">Não existem datas suficientes para montar a linha temporal.</div>';
        return;
    }

    const todosMeses = [...new Set([...previsto.keys(), ...chegada.keys()])].sort((a, b) => a - b);
    const rotulos = todosMeses.map(t => rotuloMes(new Date(t)));
    const yPrevisto = todosMeses.map(t => previsto.get(t) || 0);
    const yChegada = todosMeses.map(t => chegada.get(t) || 0);

    const divMensal = document.createElement('div');
    const divAcumulado = document.createElement('div');
    container.append(divMensal, divAcumulado);

    Plotly.newPlot(divMensal, [
        { x: rotulos, y: yPrevisto, name: 'Previsão de chegada na obra', type: 'bar', marker: { color: CORES.azul },
          text: yPrevisto.map(fmtNum), textposition: 'outside' },
        { x: rotulos, y: yChegada, name: 'Chegada realizada — NEM', type: 'bar', marker: { color: CORES.verde },
          text: yChegada.map(fmtNum), textposition: 'outside' }
    ], Object.assign(layoutBase('Materiais no mês'), {
        height: 325, showlegend: true, legend: { orientation: 'h', y: 1.15 }
    }), CONFIG_PLOT);

    Plotly.newPlot(divAcumulado, [
        { x: rotulos, y: acumular(yPrevisto), name: 'Previsão de chegada na obra', type: 'scatter',
          mode: 'lines+markers', line: { color: CORES.azul, width: 3 } },
        { x: rotulos, y: acumular(yChegada), name: 'Chegada realizada — NEM', type: 'scatter',
          mode: 'lines+markers', line: { color: CORES.verde, width: 3 } }
    ], Object.assign(layoutBase('Acumulado'), { height: 170 }), CONFIG_PLOT);

    premissaEmHtml(container, 'Previsto considera dt_prev_entrega_obra; realizado considera toda linha com data_de_chegada_nem preenchida.');
}

function renderPipeline(container, base) {
    const contagem = new Map(STATUS_PAINEL_ORDEM.map(s => [s, 0]));
    for (const r of base) if (contagem.has(r.EtapaPainel)) contagem.set(r.EtapaPainel, contagem.get(r.EtapaPainel) + 1);
    const etapas = STATUS_PAINEL_ORDEM.map(e => STATUS_PAINEL_CURTO[e]).reverse();
    const valores = STATUS_PAINEL_ORDEM.map(e => contagem.get(e)).reverse();

    const div = document.createElement('div');
    container.appendChild(div);
    Plotly.newPlot(div, [{
        type: 'bar', orientation: 'h', y: etapas, x: valores,
        text: valores.map(fmtNum), textposition: 'outside',
        marker: { color: valores, colorscale: [[0, '#DCEFF6'], [1, CORES.azul]] },
        hovertemplate: '%{y}<br>Linhas: %{x}<extra></extra>'
    }], Object.assign(layoutBase('Linhas'), { height: 315 }), CONFIG_PLOT);
    premissaEmHtml(container, 'Materiais fornecidos pela Petrobras são consolidados na etapa Material Recebido no Projeto e não representam pendência.');
}

function renderVelocimetrosDisciplinas(container, base) {
    const porDisciplina = new Map();
    for (const r of base) {
        if (!porDisciplina.has(r.Disciplina)) porDisciplina.set(r.Disciplina, { total: 0, recebidos: 0 });
        const g = porDisciplina.get(r.Disciplina);
        g.total++;
        if (r.Recebido) g.recebidos++;
    }
    const linhas = [...porDisciplina.entries()]
        .map(([disciplina, g]) => ({
            disciplina, total: g.total, recebidos: g.recebidos,
            chegada: g.total ? Math.min(100, Math.max(0, (g.recebidos / g.total) * 100)) : 0
        }))
        .sort((a, b) => (a.chegada - b.chegada) || (b.total - a.total));

    const cards = linhas.map(l => {
        const cor = l.chegada >= 90 ? CORES.verde : l.chegada >= 70 ? CORES.amarelo : CORES.vermelho;
        const nomeCompleto = escapar(l.disciplina);
        const nome = escapar(disciplinaCurta(l.disciplina));
        return '<div class="sup-gauge-card" style="--gauge:' + cor + '">' +
            '<div class="sup-gauge-title" title="' + nomeCompleto + '">' + nome + '</div>' +
            '<svg viewBox="0 0 120 72" role="img" aria-label="' + l.chegada.toFixed(1) + '% recebido">' +
            '<path class="sup-gauge-bg" pathLength="100" d="M10 62 A50 50 0 0 1 110 62"/>' +
            '<path class="sup-gauge-value" pathLength="100" stroke-dasharray="' + l.chegada.toFixed(1) + ' 100" d="M10 62 A50 50 0 0 1 110 62"/>' +
            '<text x="60" y="53" text-anchor="middle">' + fmtPct(l.chegada) + '</text></svg>' +
            '<div class="sup-gauge-foot"><span>' + fmtNum(l.recebidos) + ' recebidas</span><b>' + fmtNum(l.total) + ' total</b></div>' +
            '</div>';
    }).join('');
    container.innerHTML = '<div class="sup-gauge-grid">' + cards + '</div>';
    premissaEmHtml(container, 'O percentual corresponde às linhas recebidas — incluindo fornecimento Petrobras — sobre o total de cada disciplina.');
}

function renderAlertas(container, base) {
    const total = Math.max(base.length, 1);
    const vencidos = base.filter(r => r.Vencido).length;
    const semPrev = base.filter(r => r.SemPrevisao).length;
    const compra = base.filter(r => r.Situacao === STATUS_ORDEM[0] || r.Situacao === STATUS_ORDEM[1]).length;
    const fornecedor = base.filter(r => r.Situacao === STATUS_ORDEM[2]).length;
    const naoTag = base.filter(r => r.NaoTagueado).length;
    const alertas = [
        ['CRÍTICO', fmtNum(vencidos) + ' linhas ultrapassaram a entrega prevista na obra sem chegada registrada.',
            'Priorizar cobrança por PO e fornecedor.', CORES.vermelho],
        ['PREVISIBILIDADE', fmtNum(semPrev) + ' linhas abertas não possuem previsão de entrega.',
            'Exigir data confirmada e responsável.', CORES.amarelo],
        ['CONTRATAÇÃO', fmtNum(compra) + ' linhas permanecem em cotação ou aguardando compra.',
            'Atuar nas RMs de maior impacto no cronograma.', CORES.amarelo],
        ['FORNECEDOR', fmtNum(fornecedor) + ' linhas aguardam liberação no fornecedor.',
            'Realizar expediting focado no caminho crítico.', (fornecedor / total) > 0.30 ? CORES.vermelho : CORES.amarelo],
        ['RASTREABILIDADE', fmtNum(naoTag) + ' linhas não estão plenamente tagueadas.',
            'Planejar identificação antes do recebimento/aplicação.', CORES.azul2]
    ];
    container.innerHTML = '<div class="sup-alert-grid">' + alertas.map(([nivel, texto, acao, cor]) =>
        '<div class="sup-alert" style="--cor:' + cor + '"><b>' + escapar(nivel) + '</b><span>' + escapar(texto) +
        '</span><small>Ação: ' + escapar(acao) + '</small></div>'
    ).join('') + '</div>';
}

function renderInsights(container, base) {
    function contarTop(lista, campo) {
        const m = new Map();
        for (const r of lista) m.set(r[campo], (m.get(r[campo]) || 0) + 1);
        const arr = [...m.entries()].sort((a, b) => b[1] - a[1]);
        return arr.length ? arr[0] : ['Sem ocorrência', 0];
    }
    const venc = base.filter(r => r.Vencido);
    const [topDisc, topDiscN] = contarTop(venc, 'Disciplina');
    const [topForn, topFornN] = contarTop(venc, 'Fornecedor');
    const comp = base.filter(r => r.ChegadaNem !== null && r.DataEntregaProjeto !== null);
    const otd = comp.length ? (comp.filter(r => r.NoPrazo).length / comp.length) * 100 : 0;
    const chegadasAtrasadas = base.filter(r => r.DesvioChegada !== null && r.DesvioChegada > 0);
    const atrasoMediano = mediana(chegadasAtrasadas.map(r => r.DesvioChegada));
    const corte = base.length ? base[0].DataCorte : new Date();
    const em30dias = new Date(corte.getTime() + 30 * 86400000);
    const proximas = base.filter(r => r.DataEntregaProjeto && r.DataEntregaProjeto >= corte &&
        r.DataEntregaProjeto <= em30dias && !r.Recebido).length;
    const naoTagueadoPct = base.length ? (base.filter(r => r.NaoTagueado).length / base.length) * 100 : 0;

    const itens = [
        ['Aderência à entrega', fmtPct(otd) + ' das ' + fmtNum(comp.length) + ' linhas comparáveis chegaram até a data prevista do projeto.',
            otd < 80 ? CORES.vermelho : CORES.verde, '◷'],
        ['Concentração disciplinar', disciplinaCurta(topDisc) + ' concentra ' + fmtNum(topDiscN) + ' linhas vencidas.',
            CORES.amarelo, '◆'],
        ['Exposição por fornecedor', topForn + ' lidera a exposição com ' + fmtNum(topFornN) + ' linhas vencidas.',
            CORES.vermelho, '!'],
        ['Pressão logística', fmtNum(proximas) + ' linhas têm chegada prevista nos próximos 30 dias; dimensionar recebimento e armazenagem.',
            CORES.azul2, '↘'],
        ['Chegadas após a previsão', fmtNum(chegadasAtrasadas.length) + ' linhas chegaram após a data prevista; mediana de ' + fmtNum(atrasoMediano) + ' dias.',
            CORES.amarelo, '↗'],
        ['Rastreabilidade', fmtPct(naoTagueadoPct) + ' das linhas não estão plenamente tagueadas.', CORES.azul2, '⌖']
    ];
    container.innerHTML = '<div class="sup-insight-grid">' + itens.map(i => insightHtml(...i)).join('') + '</div>';
}

