function renderRankingDisciplinas(container, base) {
    const porDisciplina = new Map();
    for (const r of base) {
        if (!porDisciplina.has(r.Disciplina)) porDisciplina.set(r.Disciplina, { total: 0, vencidos: 0 });
        const g = porDisciplina.get(r.Disciplina);
        g.total++;
        if (r.Vencido) g.vencidos++;
    }
    let linhas = [...porDisciplina.entries()].map(([disciplina, g]) => ({
        disciplina, total: g.total, vencidos: g.vencidos, risco: g.total ? (g.vencidos / g.total) * 100 : 0
    }));
    linhas.sort((a, b) => (b.vencidos - a.vencidos) || (b.risco - a.risco));
    linhas = linhas.slice(0, 10).reverse(); // barra horizontal do Plotly desenha de baixo pra cima

    const div = document.createElement('div');
    container.appendChild(div);
    Plotly.newPlot(div, [{
        type: 'bar', orientation: 'h',
        y: linhas.map(l => disciplinaCurta(l.disciplina)), x: linhas.map(l => l.vencidos),
        text: linhas.map(l => fmtNum(l.vencidos)), textposition: 'outside',
        marker: { color: linhas.map(l => l.risco), colorscale: [[0, CORES.amarelo], [0.4, '#DDA06F'], [1, CORES.vermelho]], cmin: 0, cmax: 100 },
        hovertemplate: '%{y}<br>Vencidos: %{x}<extra></extra>'
    }], Object.assign(layoutBase('Linhas vencidas'), { height: 330 }), CONFIG_PLOT);
    premissaEmHtml(container, 'O ranking considera como vencido o material sem chegada após a data prevista em dt_prev_entrega_obra.');
}

function renderDistribuicaoExposicao(container, base) {
    const faixasDef = [
        { nome: 'No prazo', min: -1, max: 0 }, { nome: '1–15', min: 0, max: 15 },
        { nome: '16–30', min: 15, max: 30 }, { nome: '31–60', min: 30, max: 60 },
        { nome: '61–90', min: 60, max: 90 }, { nome: '>90', min: 90, max: Infinity }
    ];
    const cont = new Map(faixasDef.map(f => [f.nome, 0]));
    for (const r of base) {
        if (r.DiasAtraso === null) continue; // sem previsão: fora da distribuição, como no original
        const faixa = faixasDef.find(f => r.DiasAtraso > f.min && r.DiasAtraso <= f.max) || faixasDef[faixasDef.length - 1];
        cont.set(faixa.nome, cont.get(faixa.nome) + 1);
    }
    const nomes = faixasDef.map(f => f.nome);
    const valores = nomes.map(n => cont.get(n));
    const cores = [CORES.verde, '#B9C987', CORES.amarelo, '#E7B17B', '#DB9380', CORES.vermelho];

    const div = document.createElement('div');
    container.appendChild(div);
    Plotly.newPlot(div, [{
        type: 'bar', x: nomes, y: valores, marker: { color: cores },
        text: valores.map(fmtNum), textposition: 'outside',
        hovertemplate: '%{x}<br>Linhas: %{y}<extra></extra>'
    }], Object.assign(layoutBase('Linhas'), { height: 330, xaxis: { title: 'Dias de atraso' } }), CONFIG_PLOT);
    premissaEmHtml(container, 'As faixas medem o atraso em relação à previsão de chegada na obra; linhas recebidas não são tratadas como pendência.');
}

function renderHeatmap(container, base) {
    const porDisciplinaTotal = new Map();
    for (const r of base) porDisciplinaTotal.set(r.Disciplina, (porDisciplinaTotal.get(r.Disciplina) || 0) + 1);
    const topDisciplinas = [...porDisciplinaTotal.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10).map(x => x[0]);

    const contagem = new Map();
    for (const r of base) {
        if (!STATUS_PAINEL_ORDEM.includes(r.EtapaPainel) || !topDisciplinas.includes(r.Disciplina)) continue;
        const chave = r.Disciplina + '||' + r.EtapaPainel;
        contagem.set(chave, (contagem.get(chave) || 0) + 1);
    }
    const etapasCurtas = STATUS_PAINEL_ORDEM.map(e => STATUS_PAINEL_CURTO[e]);
    const disciplinasCurtas = topDisciplinas.map(disciplinaCurta);
    const z = topDisciplinas.map(d => STATUS_PAINEL_ORDEM.map(e => contagem.get(d + '||' + e) || 0));
    const textos = z.map(linha => linha.map(v => v === 0 ? '' : fmtNum(v)));

    const div = document.createElement('div');
    container.appendChild(div);
    Plotly.newPlot(div, [{
        type: 'heatmap', z, x: etapasCurtas, y: disciplinasCurtas,
        text: textos, texttemplate: '%{text}', textfont: { size: 10 },
        colorscale: [[0, '#EEF6F8'], [0.5, '#E9D58B'], [1, CORES.vermelho]],
        showscale: true, hovertemplate: '%{y}<br>%{x}: %{z}<extra></extra>'
    }], Object.assign(layoutBase(''), { height: 360, xaxis: { tickangle: -28 }, yaxis: { automargin: true } }), CONFIG_PLOT);
    premissaEmHtml(container, 'Cada célula mostra a quantidade de linhas da disciplina posicionadas na respectiva etapa do fluxo de suprimentos.');
}

