function renderPareto(container, base) {
    const porFornecedor = new Map();
    for (const r of base) { if (r.Vencido) porFornecedor.set(r.Fornecedor, (porFornecedor.get(r.Fornecedor) || 0) + 1); }
    let linhas = [...porFornecedor.entries()].map(([fornecedor, vencidos]) => ({ fornecedor, vencidos }));
    linhas.sort((a, b) => b.vencidos - a.vencidos);
    linhas = linhas.slice(0, 12);

    if (!linhas.length) {
        container.innerHTML = '<div class="sup-sucesso">Nenhum fornecedor com linha vencida no filtro atual.</div>';
        return;
    }
    const somaTotal = linhas.reduce((s, l) => s + l.vencidos, 0);
    let acumuladoAtual = 0;
    const acumuladoArr = linhas.map(l => { acumuladoAtual += l.vencidos; return (acumuladoAtual / somaTotal) * 100; });
    const ordem = linhas.map(l => l.fornecedor);

    const div = document.createElement('div');
    container.appendChild(div);
    Plotly.newPlot(div, [
        { type: 'bar', x: ordem, y: linhas.map(l => l.vencidos), name: 'Vencidos', marker: { color: CORES.vermelho },
          text: linhas.map(l => fmtNum(l.vencidos)), textposition: 'outside',
          hovertemplate: '%{x}<br>Vencidos: %{y}<extra></extra>' },
        { type: 'scatter', mode: 'lines+markers', x: ordem, y: acumuladoArr, name: 'Acumulado (%)', yaxis: 'y2',
          line: { color: CORES.amarelo, width: 3 }, hovertemplate: '%{x}<br>Acumulado: %{y:.1f}%<extra></extra>' }
    ], Object.assign(layoutBase('Linhas vencidas'), {
        height: 340, xaxis: { tickangle: -40 }, showlegend: true, legend: { orientation: 'h', y: 1.15 },
        yaxis2: { title: 'Acumulado (%)', overlaying: 'y', side: 'right', range: [0, 105], showgrid: false }
    }), CONFIG_PLOT);
    premissaEmHtml(container, 'O Pareto contabiliza linhas cuja previsão de chegada na obra venceu e que ainda não possuem recebimento confirmado.');
}

function renderMatrizFornecedores(container, base) {
    const porFornecedor = new Map();
    for (const r of base) {
        if (!porFornecedor.has(r.Fornecedor)) porFornecedor.set(r.Fornecedor, { linhas: 0, vencidos: 0, semPrevisao: 0, recebidos: 0 });
        const g = porFornecedor.get(r.Fornecedor);
        g.linhas++;
        if (r.Vencido) g.vencidos++;
        if (r.SemPrevisao) g.semPrevisao++;
        if (r.Recebido) g.recebidos++;
    }
    const pontos = [...porFornecedor.entries()]
        .filter(([f]) => f !== 'Não informado')
        .map(([fornecedor, g]) => ({
            fornecedor, linhas: g.linhas, semPrevisao: g.semPrevisao,
            exposicao: g.linhas ? (g.vencidos / g.linhas) * 100 : 0,
            recebimento: g.linhas ? (g.recebidos / g.linhas) * 100 : 0
        }));

    const div = document.createElement('div');
    container.appendChild(div);
    const tamanhos = pontos.map(p => 8 + Math.sqrt(p.semPrevisao) * 4);
    Plotly.newPlot(div, [{
        type: 'scatter', mode: 'markers', x: pontos.map(p => p.linhas), y: pontos.map(p => p.exposicao),
        text: pontos.map(p => p.fornecedor),
        marker: {
            size: tamanhos, color: pontos.map(p => p.recebimento),
            colorscale: [[0, CORES.vermelho], [0.5, CORES.amarelo], [1, CORES.verde]], cmin: 0, cmax: 100,
            line: { color: 'white', width: 1 }, opacity: 0.78, showscale: true, colorbar: { title: 'Recebimento' }
        },
        hovertemplate: '<b>%{text}</b><br>Linhas: %{x}<br>Exposição: %{y:.1f}%<extra></extra>'
    }], Object.assign(layoutBase('Linhas vencidas (%)'), {
        height: 370, xaxis: { title: 'Volume de linhas' }, yaxis: { range: [0, 100] }
    }), CONFIG_PLOT);
    premissaEmHtml(container, 'Cada ponto representa um fornecedor; tamanho indica ausência de previsão, cor indica recebimento e altura indica exposição a atraso.');
}

