function renderVisaoEntregas(container, base, obterDimensao, tituloDimensao, comDescricaoPO) {
    const resumo = resumoEntregas(base, obterDimensao).filter(g => g.dimensao !== 'Não informado');
    if (!resumo.length) {
        container.innerHTML = '<div class="sup-info">Não existem registros com ' + tituloDimensao.toLowerCase() + ' informado no filtro atual.</div>';
        return;
    }

    const total = resumo.reduce((s, g) => s + g.Linhas, 0);
    const recebidos = resumo.reduce((s, g) => s + g.Recebidos, 0);
    const vencidos = resumo.reduce((s, g) => s + g.Vencidos, 0);
    const recebPct = total ? (recebidos / total) * 100 : 0;
    const codigosTotais = resumo.reduce((s, g) => s + g.Codigos, 0);

    const kpis = [
        [tituloDimensao + 's', fmtNum(resumo.length), 'com movimentação', 'base filtrada', CORES.azul, 100, '→'],
        ['Linhas vinculadas', fmtNum(total), 'cobertura', fmtNum(codigosTotais) + ' códigos', CORES.azul2, 100, '→'],
        ['Materiais recebidos', fmtNum(recebidos), '≥ 95%', fmtPct(recebPct), recebPct >= 95 ? CORES.verde : CORES.amarelo, recebPct, '↗'],
        ['Linhas vencidas', fmtNum(vencidos), '0 crítico', fmtPct(total ? vencidos / total * 100 : 0),
            vencidos ? CORES.vermelho : CORES.verde, 100 - (total ? vencidos / total * 100 : 0), '!']
    ];
    const divKpi = document.createElement('div');
    divKpi.className = 'sup-mini-kpi';
    divKpi.innerHTML = kpis.map(k => cardHtml(...k)).join('');
    container.appendChild(divKpi);

    let colunas = [tituloDimensao, 'Linhas', 'Codigos', 'RMs', 'POs', 'Recebidos', 'Vencidos', 'Sem previsão', 'Recebimento (%)', 'Aderência (%)'];
    let larguras = {
        [tituloDimensao]: 24, Linhas: 7, Codigos: 7, RMs: 6, POs: 6, Recebidos: 7, Vencidos: 7,
        'Sem previsão': 8, 'Recebimento (%)': 14, 'Aderência (%)': 14
    };

    const tabelaOrdenada = resumo.slice().sort((a, b) => (b.Vencidos - a.Vencidos) || (b.Linhas - a.Linhas));
    let linhasTabela = tabelaOrdenada.map(g => ({
        [tituloDimensao]: g.dimensao, Linhas: g.Linhas, Codigos: g.Codigos, RMs: g.RMs, POs: g.POs,
        Recebidos: g.Recebidos, Vencidos: g.Vencidos, 'Sem previsão': g.SemPrevisao,
        'Recebimento (%)': g.RecebimentoPct, 'Aderência (%)': g.AderenciaPct
    }));

    if (comDescricaoPO) {
        const descPorPO = new Map();
        for (const r of base) {
            if (r.PO === 'Não informado') continue;
            if (!descPorPO.has(r.PO) && r.DescricaoAF !== 'Não informado') descPorPO.set(r.PO, r.DescricaoAF);
        }
        colunas = colunas.filter(c => c !== 'POs');
        colunas.splice(1, 0, 'Descrição');
        larguras = {
            [tituloDimensao]: 12, 'Descrição': 24, Linhas: 7, Codigos: 7, RMs: 6,
            Recebidos: 7, Vencidos: 7, 'Sem previsão': 8, 'Recebimento (%)': 11, 'Aderência (%)': 11
        };
        linhasTabela.forEach(l => {
            l['Descrição'] = descPorPO.get(l[tituloDimensao]) || 'Não informado';
            delete l['POs'];
        });
    }

    container.insertAdjacentHTML('beforeend', bandHtml('DETALHAMENTO POR ' + tituloDimensao.toUpperCase(), 'visão completa da base filtrada'));
    container.insertAdjacentHTML('beforeend', tabelaCompactaHtml(linhasTabela, colunas, larguras, ['Recebimento (%)', 'Aderência (%)']));
    premissaEmHtml(container, 'Vencido significa previsão de chegada na obra ultrapassada e ausência de recebimento confirmado por NEM ou status recebido/Petrobras.');
}

function renderAtendimentoRM(container, base) {
    let resumo = resumoEntregas(base, r => r.RM).filter(g => g.dimensao !== 'Não informado');
    if (!resumo.length) {
        container.innerHTML = '<div class="sup-info">Não existem RMs informadas no filtro atual.</div>';
        return;
    }

    const porRM = new Map();
    for (const r of base) {
        if (r.RM === 'Não informado') continue;
        if (!porRM.has(r.RM)) porRM.set(r.RM, { comPO: 0, total: 0, unidades: new Set() });
        const g = porRM.get(r.RM);
        g.total++;
        if (r.PO !== 'Não informado') g.comPO++;
        g.unidades.add(r.UnidMedida);
    }
    resumo = resumo.map(g => {
        const extra = porRM.get(g.dimensao) || { comPO: 0, total: 1, unidades: new Set() };
        return {
            ...g,
            ContratacaoPct: extra.total ? (extra.comPO / extra.total) * 100 : 0,
            UnidadesDistintas: extra.unidades.size,
            SaldoLinhas: g.Linhas - g.Recebidos
        };
    });

    const totalRM = resumo.length;
    const concluidas = resumo.filter(g => g.RecebimentoPct >= 100).length;
    const semPO = resumo.filter(g => g.ContratacaoPct < 100).length;
    const criticas = resumo.filter(g => g.Vencidos > 0).length;
    const kpis = [
        ['RMs monitoradas', fmtNum(totalRM), 'base filtrada', fmtNum(concluidas) + ' concluídas', CORES.azul, 100, '→'],
        ['RMs concluídas', fmtNum(concluidas), '100% recebidas', fmtPct(concluidas / totalRM * 100), CORES.verde, concluidas / totalRM * 100, '↗'],
        ['RMs sem PO completa', fmtNum(semPO), '0 pendência', 'cobertura por linha', semPO ? CORES.amarelo : CORES.verde, 100 - semPO / totalRM * 100, '!'],
        ['RMs com vencidos', fmtNum(criticas), '0 crítico', 'priorizar atendimento', criticas ? CORES.vermelho : CORES.verde, 100 - criticas / totalRM * 100, '!']
    ];
    const divKpi = document.createElement('div');
    divKpi.className = 'sup-mini-kpi';
    divKpi.innerHTML = kpis.map(k => cardHtml(...k)).join('');
    container.appendChild(divKpi);

    const tabela = resumo.slice().sort((a, b) => (b.Vencidos - a.Vencidos) || (a.RecebimentoPct - b.RecebimentoPct) || (b.Linhas - a.Linhas));
    container.insertAdjacentHTML('beforeend', bandHtml('DETALHAMENTO DO ATENDIMENTO DE RM', 'contratação, recebimento e risco'));

    const linhasTabela = tabela.map(g => ({
        RM: g.dimensao, Linhas: g.Linhas, Codigos: g.Codigos, POs: g.POs, Recebidos: g.Recebidos,
        'Saldo linhas': g.SaldoLinhas, Vencidos: g.Vencidos, 'Sem previsão': g.SemPrevisao,
        'Contratação (%)': g.ContratacaoPct, 'Recebimento (%)': g.RecebimentoPct, 'Aderência (%)': g.AderenciaPct,
        'Unidades distintas': g.UnidadesDistintas
    }));
    const colunasRM = ['RM', 'Linhas', 'Codigos', 'POs', 'Recebidos', 'Saldo linhas', 'Vencidos', 'Sem previsão',
        'Contratação (%)', 'Recebimento (%)', 'Aderência (%)', 'Unidades distintas'];
    const largurasRM = {
        RM: 14, Linhas: 6, Codigos: 6, POs: 5, Recebidos: 7, 'Saldo linhas': 7, Vencidos: 6, 'Sem previsão': 7,
        'Contratação (%)': 12, 'Recebimento (%)': 12, 'Aderência (%)': 12, 'Unidades distintas': 6
    };
    container.insertAdjacentHTML('beforeend', tabelaCompactaHtml(linhasTabela, colunasRM, largurasRM, ['Contratação (%)', 'Recebimento (%)', 'Aderência (%)']));
    premissaEmHtml(container, 'O atendimento da RM é medido por cobertura de linhas, evitando somar unidades incompatíveis como peças, metros, kg, kits e conjuntos.');
}

