/** Compara mantendo null sempre por último, igual ao comportamento do pandas com NaN. */
function compararComNuloPorUltimo(a, b) {
    if (a === null && b === null) return 0;
    if (a === null) return 1;
    if (b === null) return -1;
    return b - a;
}

function renderOperacaoDetalhada(container, base) {
    container.insertAdjacentHTML('beforeend', bandHtml('TOP 100 MATERIAIS PRIORITÁRIOS', 'ordenados por criticidade, atraso e ausência de previsão'));

    const ordenado = base.slice().sort((r1, r2) =>
        (r2.ScoreRisco - r1.ScoreRisco) ||
        compararComNuloPorUltimo(r1.DiasAtraso, r2.DiasAtraso) ||
        compararComNuloPorUltimo(r1.Aging, r2.Aging)
    ).slice(0, 100);

    const linhasTabela = ordenado.map(r => ({
        Criticidade: r.Criticidade, 'Score risco': r.ScoreRisco, Disciplina: r.Disciplina, 'Código': r.Codigo,
        Material: r.DescricaoMaterial, RM: r.RM, PO: r.PO, Fornecedor: r.Fornecedor, 'Situação': r.Situacao,
        'Previsão na obra': r.DataEntregaProjeto ? formatarDataBR(r.DataEntregaProjeto) : '—',
        'Chegada NEM': r.ChegadaNem ? formatarDataBR(r.ChegadaNem) : '—',
        'Dias atraso': r.DiasAtraso === null ? 0 : r.DiasAtraso
    }));
    const colunas = ['Criticidade', 'Score risco', 'Disciplina', 'Código', 'Material', 'RM', 'PO', 'Fornecedor',
        'Situação', 'Previsão na obra', 'Chegada NEM', 'Dias atraso'];
    const larguras = {
        Criticidade: 6, 'Score risco': 6, Disciplina: 8, 'Código': 7, Material: 20, RM: 7, PO: 7,
        Fornecedor: 11, 'Situação': 10, 'Previsão na obra': 6, 'Chegada NEM': 6, 'Dias atraso': 6
    };
    container.insertAdjacentHTML('beforeend', tabelaCompactaHtml(linhasTabela, colunas, larguras, []));

    const legenda = document.createElement('p');
    legenda.className = 'sup-caption';
    legenda.textContent = 'Quantidades físicas devem ser analisadas por unidade de medida. O painel evita somar peças, metros, kg e conjuntos em um único total.';
    container.appendChild(legenda);
}

