let baseTotal = [];
let baseFiltrada = [];
let abaAtiva = 0;
const filtros = { inicio: null, fim: null, disciplinas: [], tags: [], fornecedores: [], status: [] };

function aplicarFiltros() {
    let base = baseTotal;
    const { inicio, fim, disciplinas, tags, fornecedores, status } = filtros;
    if (inicio && fim) {
        const fimExclusivo = new Date(fim.getTime() + 86400000);
        base = base.filter(r => r.DataEntregaProjeto === null ||
            (r.DataEntregaProjeto.getTime() >= inicio.getTime() && r.DataEntregaProjeto.getTime() < fimExclusivo.getTime()));
    }
    if (disciplinas.length) base = base.filter(r => disciplinas.includes(r.Disciplina));
    if (tags.length) base = base.filter(r => tags.includes(r.Tagueado));
    if (fornecedores.length) base = base.filter(r => fornecedores.includes(r.Fornecedor));
    if (status.length) base = base.filter(r => status.includes(r.EtapaPainel));
    baseFiltrada = base;
}

/** Dropdown de checkboxes com busca — equivalente compacto ao st.multiselect. */
function criarMultiSelect(rotulo, opcoes, aoMudar) {
    const raiz = document.createElement('div');
    raiz.className = 'sup-filtro';

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'sup-filtro-btn';

    const painel = document.createElement('div');
    painel.className = 'sup-filtro-painel';
    painel.hidden = true;

    const busca = document.createElement('input');
    busca.type = 'search'; busca.className = 'campo sup-filtro-busca'; busca.placeholder = 'Filtrar...';
    painel.appendChild(busca);

    const lista = document.createElement('div');
    lista.className = 'sup-filtro-lista';
    painel.appendChild(lista);

    const selecionados = new Set();

    function atualizarRotulo() {
        btn.textContent = selecionados.size ? rotulo + ' (' + selecionados.size + ')' : rotulo;
        btn.classList.toggle('ativo', selecionados.size > 0);
    }

    function desenharLista() {
        const termo = busca.value.trim().toLowerCase();
        lista.innerHTML = '';
        opcoes.filter(o => !termo || o.toLowerCase().includes(termo)).forEach(o => {
            const item = document.createElement('label');
            item.className = 'sup-filtro-item';
            const check = document.createElement('input');
            check.type = 'checkbox';
            check.checked = selecionados.has(o);
            check.addEventListener('change', () => {
                check.checked ? selecionados.add(o) : selecionados.delete(o);
                atualizarRotulo();
                aoMudar([...selecionados]);
            });
            const span = document.createElement('span');
            span.textContent = o;
            item.append(check, span);
            lista.appendChild(item);
        });
    }
    busca.addEventListener('input', desenharLista);
    btn.addEventListener('click', () => {
        painel.hidden = !painel.hidden;
        if (!painel.hidden) desenharLista();
    });
    document.addEventListener('click', e => { if (!raiz.contains(e.target)) painel.hidden = true; });

    atualizarRotulo();
    raiz.append(btn, painel);
    return raiz;
}

function aoFiltroMudar() {
    aplicarFiltros();
    atualizarKPIsTopo();
    renderizarAbaAtiva();
}

function montarFiltros(container) {
    container.innerHTML = '';
    const linha = document.createElement('div');
    linha.className = 'sup-filtros-linha';

    const datasValidas = baseTotal.map(r => r.DataEntregaProjeto).filter(Boolean);
    const dataMin = datasValidas.length ? new Date(Math.min(...datasValidas.map(d => +d))) : new Date();
    const dataMax = datasValidas.length ? new Date(Math.max(...datasValidas.map(d => +d))) : new Date();
    filtros.inicio = dataMin; filtros.fim = dataMax;

    function campoData(rotulo, valorInicial, aoMudar) {
        const wrap = document.createElement('div');
        wrap.className = 'sup-filtro-data';
        const label = document.createElement('span'); label.textContent = rotulo;
        const input = document.createElement('input');
        input.type = 'date'; input.className = 'campo';
        input.value = paraISO(valorInicial);
        input.addEventListener('change', () => {
            aoMudar(input.value ? new Date(input.value + 'T00:00:00Z') : null);
            aoFiltroMudar();
        });
        wrap.append(label, input);
        return wrap;
    }
    linha.appendChild(campoData('De', filtros.inicio, v => { filtros.inicio = v; }));
    linha.appendChild(campoData('Até', filtros.fim, v => { filtros.fim = v; }));

    const disciplinas = [...new Set(baseTotal.map(r => r.Disciplina))].sort();
    const tags = [...new Set(baseTotal.map(r => r.Tagueado))].sort();
    const fornecedores = [...new Set(baseTotal.map(r => r.Fornecedor))].sort();
    const statusDisponiveis = STATUS_PAINEL_ORDEM.filter(s => baseTotal.some(r => r.EtapaPainel === s));

    linha.appendChild(criarMultiSelect('Disciplina', disciplinas, sel => { filtros.disciplinas = sel; aoFiltroMudar(); }));
    linha.appendChild(criarMultiSelect('Tagueamento', tags, sel => { filtros.tags = sel; aoFiltroMudar(); }));
    linha.appendChild(criarMultiSelect('Fornecedor', fornecedores, sel => { filtros.fornecedores = sel; aoFiltroMudar(); }));
    linha.appendChild(criarMultiSelect('Situação', statusDisponiveis.map(s => STATUS_PAINEL_CURTO[s]), sel => {
        filtros.status = statusDisponiveis.filter(s => sel.includes(STATUS_PAINEL_CURTO[s]));
        aoFiltroMudar();
    }));

    container.appendChild(linha);
    const nota = document.createElement('div');
    nota.className = 'sup-filter-note';
    nota.textContent = 'Cliente: Petrobras • Projeto: Consórcio UHN • filtros vazios exibem todos os registros.';
    container.appendChild(nota);
}

