// KPIs do topo
// ---------------------------------------------------------------------------

function atualizarKPIsTopo() {
    const base = baseFiltrada;
    const total = base.length;
    const receb = base.filter(r => r.Recebido).length;
    const venc = base.filter(r => r.Vencido).length;
    const semPrev = base.filter(r => r.SemPrevisao).length;
    const comparaveis = base.filter(r => r.ChegadaNem !== null && r.DataEntregaProjeto !== null);
    const otd = comparaveis.length ? (comparaveis.filter(r => r.NoPrazo).length / comparaveis.length) * 100 : 0;
    const tag = total ? (base.filter(r => !r.NaoTagueado).length / total) * 100 : 0;
    const coberturaPrev = total ? (base.filter(r => !r.SemPrevisao).length / total) * 100 : 0;
    const recebPct = total ? receb / total * 100 : 0;
    const vencPct = total ? venc / total * 100 : 0;
    const desvioMed = mediana(base.map(r => r.DesvioChegada).filter(v => v !== null && v > 0));
    const saude = Math.max(0, Math.min(100, 0.35 * otd + 0.25 * (100 - vencPct) + 0.20 * coberturaPrev + 0.20 * tag));
    const saudeCor = saude >= 85 ? CORES.verde : saude >= 70 ? CORES.amarelo : CORES.vermelho;
    const codigosUnicos = new Set(base.map(r => r.Codigo)).size;
    const rmsUnicas = new Set(base.map(r => r.RM)).size;
    const posUnicas = new Set(base.map(r => r.PO)).size;
    const naoTagueados = base.filter(r => r.NaoTagueado).length;

    const cards = [
        ['Linhas de materiais', fmtNum(total), 'Base filtrada', fmtNum(codigosUnicos) + ' códigos', CORES.azul, 100, '→'],
        ['RMs', fmtNum(rmsUnicas), 'Cobertura total', fmtNum(posUnicas) + ' POs', CORES.azul2, 100, '→'],
        ['Recebimento', fmtPct(recebPct), '≥ 95%', fmtNum(receb) + ' linhas', recebPct >= 95 ? CORES.verde : CORES.amarelo, recebPct, '↗'],
        ['Aderência à entrega', fmtPct(otd), '≥ 90%', fmtNum(comparaveis.length) + ' comparáveis',
            otd >= 90 ? CORES.verde : CORES.vermelho, otd, otd < 90 ? '↘' : '↗'],
        ['Vencidos', fmtNum(venc), '0 crítico', fmtPct(vencPct), venc ? CORES.vermelho : CORES.verde, 100 - vencPct, '!'],
        ['Previsibilidade', fmtPct(coberturaPrev), '≥ 95%', fmtNum(semPrev) + ' sem data',
            coberturaPrev >= 95 ? CORES.verde : CORES.amarelo, coberturaPrev, '→'],
        ['Tagueamento', fmtPct(tag), '≥ 95%', fmtNum(naoTagueados) + ' pendentes',
            tag >= 95 ? CORES.verde : CORES.amarelo, tag, '→'],
        ['Saúde operacional', fmtPct(saude), '≥ 85%', 'Atraso med.: ' + fmtNum(desvioMed) + ' dias',
            saudeCor, saude, saude >= 85 ? '↗' : '↘']
    ];
    document.getElementById('sup-kpis').innerHTML = cards.map(c => cardHtml(...c)).join('');
}

